const PROFESSIONALS_PER_DELIVERY_PAGE = 10;

function LifecycleDeliveryLogs({
  deliveries,
  resendingDispatchId,
  onResend
}: {
  deliveries: any[];
  resendingDispatchId: string | null;
  onResend: (delivery: any) => void;
}) {
  const [page, setPage] = useState(1);
  const groupedDeliveries = useMemo(() => groupLifecycleDeliveries(deliveries), [deliveries]);
  const pagination = useMemo(
    () => paginateLifecycleDeliveryGroups(groupedDeliveries, page, PROFESSIONALS_PER_DELIVERY_PAGE),
    [groupedDeliveries, page]
  );

  useEffect(() => {
    setPage(1);
  }, [deliveries]);

  useEffect(() => {
    if (page !== pagination.page) setPage(pagination.page);
  }, [page, pagination.page]);

  if (deliveries.length === 0) {
    return <EmptyState icon={ScrollText} title="Nenhum registro de envio" description="Os disparos processados pela fila aparecerão aqui." />;
  }

  return (
    <div className="space-y-4" data-testid="lifecycle-delivery-groups">
      <div className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-brand-border bg-white px-4 py-3">
        <div>
          <strong className="block text-sm text-brand-text">Envios agrupados por profissional</strong>
          <span className="text-xs text-brand-text-muted">Até {PROFESSIONALS_PER_DELIVERY_PAGE} profissionais por página · {pagination.total} profissionais com registros</span>
        </div>
        <span className="rounded-full bg-brand-bg px-3 py-1 text-xs font-semibold text-brand-primary">Página {pagination.page} de {pagination.totalPages}</span>
      </div>

      {pagination.groups.map((group: LifecycleDeliveryGroup, index) => (
        <details key={group.professionalId} open={index === 0} className="overflow-hidden rounded-xl border border-brand-border bg-white shadow-sm">
          <summary className="flex cursor-pointer list-none flex-wrap items-center justify-between gap-3 px-4 py-3 transition-colors hover:bg-brand-bg/40">
            <div className="min-w-0">
              <strong className="block truncate text-sm text-brand-text">{group.recipientName}</strong>
              <span className="block truncate text-xs text-brand-text-muted">{group.recipientEmail}</span>
            </div>
            <div className="flex items-center gap-3 text-xs text-brand-text-muted">
              <span>{group.deliveries.length} {group.deliveries.length === 1 ? 'envio' : 'envios'}</span>
              <span>Último: {group.latestAt ? new Date(group.latestAt).toLocaleString('pt-BR') : '—'}</span>
            </div>
          </summary>

          <div className="overflow-x-auto border-t border-brand-border">
            <table className="w-full min-w-[1120px] table-fixed text-left text-sm">
              <thead className="bg-brand-bg text-xs uppercase text-brand-text-muted">
                <tr>
                  <th className="w-[19%] p-3">Modelo enviado</th>
                  <th className="w-[9%] p-3">Status</th>
                  <th className="w-[15%] p-3">Canais</th>
                  <th className="w-[17%] p-3">Enviada/agendada</th>
                  <th className="w-[9%] p-3">Tentativas</th>
                  <th className="w-[24%] p-3">Motivo</th>
                  <th className="w-[7%] p-3 text-right">Ação</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-brand-border">
                {group.deliveries.map((item) => (
                  <tr key={item.id} className="hover:bg-brand-bg/40">
                    <td className="p-3">
                      <strong className="block max-w-full truncate" title={item.template_name}>{item.template_name}</strong>
                      <span className="block max-w-full truncate text-xs text-brand-text-muted" title={item.template_key}>{item.template_reference}</span>
                    </td>
                    <td className="p-3">
                      <span className={'rounded-full px-2.5 py-1 text-xs font-medium ' + (item.status === 'sent' ? 'bg-emerald-100 text-emerald-700' : item.status === 'failed' ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-600')}>
                        {deliveryStatusLabel(item.status)}
                      </span>
                    </td>
                    <td className="p-3">
                      <div className="flex items-center gap-1.5">
                        <ChannelDeliveryIcon channel="email" status={channelDeliveryStatus(item, 'email')} />
                        <ChannelDeliveryIcon channel="push" status={channelDeliveryStatus(item, 'push')} />
                        <ChannelDeliveryIcon channel="whatsapp" status={channelDeliveryStatus(item, 'whatsapp')} />
                      </div>
                    </td>
                    <td className="p-3 whitespace-nowrap">{(item.sent_at || item.scheduled_for) ? new Date(item.sent_at || item.scheduled_for).toLocaleString('pt-BR') : '—'}</td>
                    <td className="p-3">{item.attempt_count}/{item.max_attempts}</td>
                    <td className="max-w-full truncate p-3" title={item.skip_reason || item.failure_reason || ''}>{item.skip_reason || item.failure_reason || '—'}</td>
                    <td className="p-3 text-right">
                      <button onClick={() => onResend(item)} disabled={resendingDispatchId === item.id} title="Reenviar mensagem pelos canais habilitados" className="btn-outline inline-flex items-center gap-1.5 p-1.5 text-xs disabled:cursor-not-allowed disabled:opacity-50">
                        {resendingDispatchId === item.id ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />}
                        <span className="sr-only">Reenviar</span>
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>
      ))}

      <nav className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-brand-border bg-white px-4 py-3" aria-label="Paginação dos profissionais com envios">
        <span className="text-xs text-brand-text-muted">Mostrando profissionais {(pagination.page - 1) * pagination.pageSize + 1}–{Math.min(pagination.page * pagination.pageSize, pagination.total)} de {pagination.total}</span>
        <div className="flex items-center gap-2">
          <button type="button" onClick={() => setPage((current) => Math.max(1, current - 1))} disabled={pagination.page <= 1} className="btn-outline px-3 py-1.5 text-xs disabled:cursor-not-allowed disabled:opacity-50">Anterior</button>
          <span className="min-w-20 text-center text-xs font-semibold text-brand-text">{pagination.page} / {pagination.totalPages}</span>
          <button type="button" onClick={() => setPage((current) => Math.min(pagination.totalPages, current + 1))} disabled={pagination.page >= pagination.totalPages} className="btn-outline px-3 py-1.5 text-xs disabled:cursor-not-allowed disabled:opacity-50">Próxima</button>
        </div>
      </nav>
    </div>
  );
}

export default function LifecycleAdmin() {
  const navigate = useNavigate();
  const location = useLocation();
  const lifecycleView = lifecycleViewFromPath(location.pathname);
  const [tab, setTab] = useState<Tab>(lifecycleView.tab);
  const [campaignTab, setCampaignTab] = useState<CampaignTab>(lifecycleView.campaignTab);
  const [overview, setOverview] = useState<any>(null);
  const [campaigns, setCampaigns] = useState<any[]>([]);
  const [rules, setRules] = useState<any[]>([]);
  const [users, setUsers] = useState<any[]>([]);
  const [deliveries, setDeliveries] = useState<any[]>([]);
  const [preferences, setPreferences] = useState<any[]>([]);
  const [runtime, setRuntime] = useState({ send_enabled: false, dry_run: true, max_batch_size: 25, global_outage: false, test_recipient_email: '' });
  const [steps, setSteps] = useState<Record<string, any[]>>({});
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [editingTemplateId, setEditingTemplateId] = useState<string | null>(null);
  const [templateDraft, setTemplateDraft] = useState<TemplateDraft | null>(null);
  const [richTextHtml, setRichTextHtml] = useState('');
  const [templateSaving, setTemplateSaving] = useState(false);
  const [sendingTestStepId, setSendingTestStepId] = useState<string | null>(null);
  const [testStepMessage, setTestStepMessage] = useState('');
  const [sendingUserId, setSendingUserId] = useState<string | null>(null);
  const [restartingUserId, setRestartingUserId] = useState<string | null>(null);
  const [resendingDispatchId, setResendingDispatchId] = useState<string | null>(null);
  const richTextEditorRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const normalizedPath = location.pathname.replace(/\/+$/, '') || '/';
    const canonicalPath = lifecyclePathFor(lifecycleView.tab, lifecycleView.campaignTab);
    if (normalizedPath !== canonicalPath) {
      navigate(canonicalPath, { replace: true });
      return;
    }
    setTab(lifecycleView.tab);
    setCampaignTab(lifecycleView.campaignTab);
  }, [lifecycleView.campaignTab, lifecycleView.tab, location.pathname, navigate]);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [overviewData, campaignData, rulesData, usersData, deliveryData, preferencesData, settingsData] = await Promise.all([
        api('/api/admin/lifecycle/overview'),
        api('/api/admin/lifecycle/campaigns'),
        api('/api/admin/lifecycle/rules'),
        api('/api/admin/lifecycle/users'),
        api('/api/admin/lifecycle/deliveries?limit=500'),
        api('/api/admin/lifecycle/preferences'),
        api('/api/admin/lifecycle/settings')
      ]);
      const campaignList = campaignData.campaigns || [];
      const stepEntries = await Promise.all(campaignList.map(async (campaign: any) => {
        try {
          const data = await api('/api/admin/lifecycle/campaigns/' + campaign.id + '/steps');
          return [campaign.id, data.steps || []] as const;
        } catch {
          return [campaign.id, []] as const;
        }
      }));

      setOverview(overviewData);
      setCampaigns(campaignList);
      setSteps(Object.fromEntries(stepEntries));
      setRules(rulesData.rules || []);
      setUsers(usersData.users || []);
      setDeliveries(deliveryData.deliveries || []);
      setPreferences(preferencesData.preferences || []);
      setRuntime((current) => settingsData.runtime || current);
    } catch (err: any) {
      setError(err.message || 'Falha ao carregar Onboarding dos Usuários.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  useEffect(() => {
    if (editingTemplateId && richTextEditorRef.current && richTextEditorRef.current.innerHTML !== richTextHtml) {
      richTextEditorRef.current.innerHTML = richTextHtml;
    }
  }, [editingTemplateId, richTextHtml]);

  const updateCampaign = async (campaign: any, status: string) => {
    try {
      await api('/api/admin/lifecycle/campaigns/' + campaign.id, { method: 'PUT', body: JSON.stringify({ status }) });
      setMessage('Campanha atualizada.');
      await load();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const updateStep = async (step: any) => {
    try {
      await api('/api/admin/lifecycle/steps/' + step.id, { method: 'PUT', body: JSON.stringify({ status: step.status === 'active' ? 'draft' : 'active' }) });
      setMessage('Passo atualizado.');
      await load();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const startTemplateEdit = (step: any) => {
    setEditingTemplateId(step.id);
    setTemplateDraft(templateDraftFromStep(step));
    setRichTextHtml(markdownToEditorHtml(step.body_markdown || ''));
    setTestStepMessage('');
    setError('');
    setMessage('');
  };

  const cancelTemplateEdit = () => {
    setEditingTemplateId(null);
    setTemplateDraft(null);
    setRichTextHtml('');
    setTestStepMessage('');
  };

  const syncRichTextDraft = () => {
    const html = richTextEditorRef.current?.innerHTML || '';
    setRichTextHtml(html);
    setTemplateDraft((current) => current ? { ...current, body_markdown: richTextHtmlToMarkdown(html) } : current);
  };

  const applyRichTextCommand = (command: string, value?: string) => {
    const editor = richTextEditorRef.current;
    if (!editor) return;
    editor.focus();
    document.execCommand(command, false, value);
    syncRichTextDraft();
  };

  const saveTemplate = async () => {
    if (!editingTemplateId || !templateDraft) return;
    if (!templateDraft.subject_template.trim() || !templateDraft.body_markdown.trim()) {
      setError('O assunto e o conteúdo do modelo são obrigatórios.');
      return;
    }

    const waitMinutesValue = Number(templateDraft.wait_minutes);
    if (!Number.isInteger(waitMinutesValue) || waitMinutesValue < 0) {
      setError('O tempo de espera deve ser um número inteiro igual ou maior que zero.');
      return;
    }

    setTemplateSaving(true);
    setError('');
    try {
      await api('/api/admin/lifecycle/steps/' + editingTemplateId, {
        method: 'PUT',
        body: JSON.stringify({
          subject_template: templateDraft.subject_template.trim(),
          preheader_template: templateDraft.preheader_template.trim() || null,
          body_markdown: templateDraft.body_markdown.trim(),
          cta_label_template: templateDraft.cta_label_template.trim() || null,
          cta_route_template: templateDraft.cta_route_template.trim() || null,
          fallback_cta_route: templateDraft.fallback_cta_route.trim() || null,
          category: templateDraft.category.trim() || 'education',
          wait_minutes: waitMinutesValue
        })
      });
      setMessage('Modelo atualizado com sucesso.');
      cancelTemplateEdit();
      await load();
    } catch (err: any) {
      setError(err.message || 'Falha ao salvar o modelo.');
    } finally {
      setTemplateSaving(false);
    }
  };

  const sendTestStep = async () => {
    if (!editingTemplate || !templateDraft || editingConditions.length === 0) return;
    const { data } = await supabase.auth.getSession();
    const adminEmail = runtime.test_recipient_email.trim() || data.session?.user?.email;
    if (!adminEmail) {
      setError('Não foi possível identificar o e-mail do administrador autenticado.');
      return;
    }
    const confirmed = await showConfirm(`Enviar um teste deste passo para ${adminEmail}?`, {
      title: "Enviar Teste",
      confirmLabel: "Enviar",
      cancelLabel: "Cancelar",
      variant: "info",
      icon: "question"
    });
    if (!confirmed) return;
    setSendingTestStepId(editingTemplate.id);
    setTestStepMessage('');
    setError('');
    setMessage('');
    try {
      const result = await api('/api/admin/lifecycle/test-email', {
        method: 'POST',
        body: JSON.stringify({
          recipientEmail: adminEmail,
          stepId: editingTemplate.id,
          subject: templateDraft.subject_template.trim(),
          preheader: templateDraft.preheader_template.trim(),
          body: templateDraft.body_markdown.trim(),
          ctaLabel: templateDraft.cta_label_template.trim(),
          ctaRoute: templateDraft.cta_route_template.trim() || templateDraft.fallback_cta_route.trim()
        })
      });
      setTestStepMessage(result.message || `E-mail de teste enviado para ${adminEmail}.`);
    } catch (err: any) {
      setTestStepMessage(err.message || 'Falha ao enviar o e-mail de teste.');
    } finally {
      setSendingTestStepId(null);
    }
  };

  const userAction = async (user: any, action: 'pause' | 'resume' | 'recalculate' | 'enroll') => {
    try {
      await api('/api/admin/lifecycle/users/' + user.id + '/' + action, { method: 'POST', body: JSON.stringify({ campaignKey: 'new_user_activation_15d' }) });
      setMessage('Usuário atualizado.');
      await load();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const forceSendCurrentStep = async (user: any, step: any) => {
    if (!step) return;
    const confirmed = await showConfirm(`Enviar agora o e-mail do passo ${step.position} para ${user.full_name || 'este usuário'}?`, {
      title: "Forçar Envio",
      confirmLabel: "Enviar Agora",
      cancelLabel: "Cancelar",
      variant: "warning",
      icon: "question"
    });
    if (!confirmed) return;
    setSendingUserId(user.id);
    setError('');
    setMessage('');
    try {
      const result = await api('/api/admin/lifecycle/users/' + user.id + '/force-send', {
        method: 'POST',
        body: JSON.stringify({ campaignKey: 'new_user_activation_15d', stepId: step.id })
      });
      setMessage(result.message || 'Mensagem do passo atual enviada pelos canais habilitados.');
      await load();
    } catch (err: any) {
      setError(err.message || 'Falha ao enviar o e-mail do passo atual.');
    } finally {
      setSendingUserId(null);
    }
  };

  const restartJourney = async (user: any) => {
    const confirmed = await showConfirm(`Reiniciar a jornada de ${user.full_name || user.google_email || 'este usuário'} desde o primeiro passo?`, {
      title: "Reiniciar Jornada",
      confirmLabel: "Reiniciar",
      cancelLabel: "Cancelar",
      variant: "danger",
      icon: "warning"
    });
    if (!confirmed) return;
    setRestartingUserId(user.id);
    setError('');
    setMessage('');
    try {
      const result = await api('/api/admin/lifecycle/users/' + user.id + '/restart', { method: 'POST', body: JSON.stringify({ campaignKey: 'new_user_activation_15d' }) });
      setMessage(result.message || 'Jornada reiniciada com sucesso.');
      await load();
    } catch (err: any) {
      setError(err.message || 'Falha ao reiniciar a jornada.');
    } finally {
      setRestartingUserId(null);
    }
  };

  const resendLifecycleDelivery = async (delivery: any) => {
    const confirmed = await showConfirm(`Reenviar este e-mail para ${delivery.recipient_name || delivery.recipient_email || 'o destinatário'}?`, {
      title: "Reenviar E-mail",
      confirmLabel: "Reenviar",
      cancelLabel: "Cancelar",
      variant: "info",
      icon: "question"
    });
    if (!confirmed) return;
    setResendingDispatchId(delivery.id);
    setError('');
    setMessage('');
    try {
      const result = await api('/api/admin/lifecycle/dispatches/' + delivery.id + '/resend', { method: 'POST' });
      setMessage(result.message || 'Mensagem lifecycle reenviada pelos canais habilitados.');
      await load();
    } catch (err: any) {
      setError(err.message || 'Falha ao reenviar o e-mail lifecycle.');
    } finally {
      setResendingDispatchId(null);
    }
  };

  const saveRuntime = async () => {
    try {
      await api('/api/admin/lifecycle/settings', { method: 'PUT', body: JSON.stringify(runtime) });
      setMessage('Configuração salva.');
      await load();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const tabs: Array<[Tab, string]> = [
    ['overview', 'Visão geral'],
    ['campaigns', 'Campanhas e passos'],
    ['preferences', 'Preferências'],
    ['settings', 'Configurações']
  ];
  const campaignTabs: Array<[CampaignTab, string, typeof ListChecks]> = [
    ['flows', 'Fluxos e Passos', ListChecks],
    ['instances', 'Usuários no Fluxo', Users],
    ['logs', 'Registros de Envio', ScrollText]
  ];
  const isVisibleStep = (campaign: any, step: any) => campaign.key !== 'conditional_lifecycle_messages' || step.status !== 'archived';
  const templateRows = campaigns.flatMap((campaign) => (steps[campaign.id] || []).filter((step) => isVisibleStep(campaign, step)).map((step) => ({ ...step, campaign })));
  const activationCampaign = campaigns.find((campaign) => campaign.key === 'new_user_activation_15d');
  const activationSteps = activationCampaign ? steps[activationCampaign.id] || [] : [];
  const editingTemplate = templateRows.find((step) => step.id === editingTemplateId);
  const editingConditions = editingTemplate ? [
    { label: 'Elegibilidade', key: editingTemplate.eligibility_rule_key },
    { label: 'Salto do passo', key: editingTemplate.skip_rule_key }
  ].filter((condition) => condition.key) : [];

  if (loading && !overview) return <div className="flex items-center justify-center p-12"><Loader2 className="animate-spin text-brand-primary" /></div>;

  return <div className="space-y-6">
    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
      <div>
        <h2 className="text-2xl font-bold text-brand-text">Onboarding dos Usuários</h2>
        <p className="text-sm text-brand-text-muted mt-1">Automação individual, simulação, fila e métricas de relacionamento.</p>
      </div>
      <button onClick={() => void load()} className="btn-outline inline-flex items-center gap-2 self-start"><RefreshCw size={16} /> Atualizar</button>
    </div>

    {error && <div className="rounded-lg bg-red-50 text-red-700 p-3 text-sm">{error}</div>}
    {message && <div className="rounded-lg bg-emerald-50 text-emerald-700 p-3 text-sm flex items-center gap-2"><Check size={16} />{message}</div>}

    <div className="flex gap-2 overflow-x-auto border-b border-brand-border pb-2">
      {tabs.map(([key, label]) => <button key={key} onClick={() => navigate(lifecyclePathFor(key, key === 'campaigns' ? campaignTab : 'flows'))} className={'px-3 py-2 rounded-lg text-sm whitespace-nowrap ' + (tab === key ? 'bg-brand-primary text-white' : 'text-brand-text-muted hover:bg-brand-bg')}>{label}</button>)}
    </div>

    {tab === 'overview' && <div className="space-y-6">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          ['Matriculados', overview?.metrics?.enrolled], ['Ativos', overview?.metrics?.active], ['Na fila', overview?.metrics?.queued], ['Enviados', overview?.metrics?.sent],
          ['Concluídos', overview?.metrics?.completed], ['Falhas', overview?.metrics?.failed], ['Suprimidos', overview?.metrics?.suppressed], ['Cooldown', '96h']
        ].map(([label, value]) => <div key={String(label)} className="bg-white border border-brand-border rounded-xl p-4"><span className="text-xs text-brand-text-muted block">{label}</span><strong className="text-2xl text-brand-text">{value ?? '—'}</strong></div>)}
      </div>
      <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><strong>Modo atual:</strong> {runtime.dry_run ? 'simulação / observação' : runtime.send_enabled ? 'envio habilitado' : 'envio desabilitado'} — campanhas e passos começam em rascunho.</div>
    </div>}

    {tab === 'campaigns' && <div className="space-y-6">
      <div role="tablist" aria-label="Seções de campanhas e passos" className="grid grid-cols-2 md:grid-cols-4 gap-1 rounded-xl bg-brand-bg p-1 max-w-3xl">
        {campaignTabs.map(([key, label, Icon]) => <button key={key} type="button" role="tab" aria-selected={campaignTab === key} onClick={() => navigate(lifecyclePathFor('campaigns', key))} className={'inline-flex items-center justify-center gap-2 rounded-lg px-3 py-2.5 text-sm font-medium transition-all ' + (campaignTab === key ? 'bg-white text-brand-primary shadow-sm' : 'text-brand-text-muted hover:text-brand-text')}><Icon size={15} />{label}</button>)}
      </div>

      {campaignTab === 'flows' && <div className="space-y-6">
        {campaigns.length === 0 && <EmptyState icon={ListChecks} title="Nenhuma campanha cadastrada" description="Crie uma campanha para organizar os passos da jornada." />}
        {campaigns.map((campaign) => <section key={campaign.id} className="rounded-xl border border-brand-border bg-white overflow-hidden shadow-sm">
          <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-brand-border bg-slate-50/70 p-5 md:p-6">
            <div>
              <div className="flex flex-wrap items-center gap-2"><h3 className="text-lg font-semibold text-brand-text">{campaign.name}</h3><span className={'rounded-full border px-2.5 py-1 text-xs font-semibold ' + campaignStatusClass(campaign.status)}>{campaignStatusLabel(campaign.status)}</span></div>
              <p className="mt-1 text-sm text-brand-text-muted">Público-alvo: {enrollmentModeLabel(campaign.enrollment_mode)} · {campaign.description || 'Sem descrição cadastrada'}</p>
            </div>
            <div className="flex gap-2">
              {campaign.status === 'active' ? <button onClick={() => void updateCampaign(campaign, 'paused')} className="btn-outline inline-flex items-center gap-1.5 text-xs"><CirclePause size={14} /> Pausar</button> : campaign.status !== 'archived' && <button onClick={() => void updateCampaign(campaign, 'active')} className="btn-primary inline-flex items-center gap-1.5 text-xs"><CirclePlay size={14} /> Ativar</button>}
            </div>
          </header>
          {(() => { const visibleSteps = (steps[campaign.id] || []).filter((step) => isVisibleStep(campaign, step)); return visibleSteps.length === 0 ? <div className="p-6 text-sm text-brand-text-muted">Nenhum passo encontrado nesta campanha.</div> : <div className="overflow-x-auto"><table className="w-full min-w-[820px] text-sm"><thead className="border-b border-brand-border text-brand-text-muted"><tr><th className="w-16 px-4 py-3 text-center font-medium">Ordem</th><th className="px-4 py-3 text-left font-medium">Modelo</th><th className="px-4 py-3 text-left font-medium">Espera adicional</th><th className="px-4 py-3 text-left font-medium">Tipo</th><th className="px-4 py-3 text-left font-medium">Condição</th><th className="px-4 py-3 text-left font-medium">Estado</th><th className="px-4 py-3 text-right font-medium">Ação</th></tr></thead><tbody className="divide-y divide-brand-border">{[...visibleSteps].sort((a, b) => a.position - b.position).map((step) => <tr key={step.id} className="hover:bg-brand-bg/40"><td className="bg-slate-50/60 px-4 py-4 text-center font-bold text-brand-text">{step.position}</td><td className="px-4 py-4"><strong className="block max-w-[360px] truncate font-medium text-brand-text">{step.subject_template}</strong><span className="mt-0.5 block max-w-[360px] truncate text-xs text-brand-text-muted">{step.preheader_template || step.step_key}</span></td><td className="px-4 py-4 whitespace-nowrap">{formatWaitTime(step)}</td><td className="px-4 py-4"><span className="rounded-full border border-brand-border px-2.5 py-1 text-xs font-medium">{stepType(step)}</span></td><td className="px-4 py-4"><span className={stepCondition(step, rules) === '—' ? 'text-brand-text-muted' : 'font-mono text-xs text-brand-text-muted'}>{stepCondition(step, rules)}</span></td><td className="px-4 py-4"><span className={'rounded-full px-2.5 py-1 text-xs font-medium ' + (step.status === 'active' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-600')}>{step.status === 'active' ? 'Ativo' : 'Rascunho'}</span></td><td className="px-4 py-4 text-right"><div className="inline-flex flex-wrap justify-end gap-2"><button onClick={() => startTemplateEdit(step)} className="btn-outline inline-flex items-center gap-1.5 whitespace-nowrap text-xs"><Pencil size={13} /> Editar</button><button onClick={() => void updateStep(step)} className="btn-outline whitespace-nowrap text-xs">{step.status === 'active' ? 'Voltar para rascunho' : 'Validar e ativar'}</button></div></td></tr>)}</tbody></table></div>; })()}
        </section>)}
      </div>}

      {campaignTab === 'flows' && <div className="space-y-4">
        {editingTemplate && templateDraft && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget && !templateSaving) cancelTemplateEdit(); }}>
          <form onSubmit={(event) => { event.preventDefault(); void saveTemplate(); }} role="dialog" aria-modal="true" aria-labelledby="lifecycle-template-editor-title" className="flex max-h-[92vh] w-full max-w-5xl flex-col overflow-hidden rounded-2xl border border-brand-border bg-white shadow-2xl">
            <div className="flex items-start justify-between gap-4 border-b border-brand-border bg-slate-50/80 p-5 md:p-6">
              <div><span className="text-xs font-semibold uppercase tracking-wide text-brand-primary">Editor de modelo</span><h3 id="lifecycle-template-editor-title" className="mt-1 text-lg font-semibold text-brand-text">Passo {editingTemplate.position} · {editingTemplate.campaign.name}</h3><p className="mt-1 text-xs text-brand-text-muted">As alterações serão aplicadas ao próximo processamento deste passo.</p></div>
              <button type="button" onClick={cancelTemplateEdit} disabled={templateSaving} className="rounded-lg p-2 text-brand-text-muted hover:bg-brand-bg hover:text-brand-text disabled:opacity-50" aria-label="Fechar editor"><X size={18} /></button>
            </div>

            <div className="overflow-y-auto p-5 md:p-6 space-y-5">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <label className="block"><span className="text-sm font-semibold text-brand-text">Assunto</span><input required value={templateDraft.subject_template} onChange={(event) => setTemplateDraft({ ...templateDraft, subject_template: event.target.value })} className="mt-1 w-full rounded-lg border border-brand-border px-3 py-2.5 text-sm focus:border-brand-primary focus:outline-none" /></label>
                <label className="block"><span className="text-sm font-semibold text-brand-text">Preheader</span><input value={templateDraft.preheader_template} onChange={(event) => setTemplateDraft({ ...templateDraft, preheader_template: event.target.value })} className="mt-1 w-full rounded-lg border border-brand-border px-3 py-2.5 text-sm focus:border-brand-primary focus:outline-none" /></label>
                <label className="block"><span className="text-sm font-semibold text-brand-text">Tempo de espera (minutos)</span><input required type="number" min={0} value={templateDraft.wait_minutes} onChange={(event) => setTemplateDraft({ ...templateDraft, wait_minutes: event.target.value })} className="mt-1 w-full rounded-lg border border-brand-border px-3 py-2.5 text-sm focus:border-brand-primary focus:outline-none" /><small className="mt-1 block text-xs text-brand-text-muted">{formatMinutesToReadable(templateDraft.wait_minutes)}</small></label>
              </div>

              <section className="rounded-xl border border-brand-border bg-brand-bg/40 p-4" aria-labelledby="lifecycle-conditional-messages-title">
                <div className="flex items-start gap-3">
                  <span className="mt-0.5 rounded-lg bg-white p-2 text-brand-primary shadow-sm"><ListChecks size={17} /></span>
                  <div className="min-w-0 flex-1">
                    <h4 id="lifecycle-conditional-messages-title" className="font-semibold text-brand-text">Mensagens Condicionais</h4>
                    <p className="mt-1 text-xs text-brand-text-muted">Condições configuradas para este passo antes do envio da mensagem.</p>
                    {editingConditions.length === 0 ? <p className="mt-3 rounded-lg border border-dashed border-brand-border bg-white p-3 text-sm text-brand-text-muted">Nenhuma condição configurada. Este passo será avaliado para todos os usuários elegíveis do fluxo.</p> : <div className="mt-3 grid grid-cols-1 gap-3 md:grid-cols-2">{editingConditions.map((condition) => { const rule = rules.find((item) => item.rule_key === condition.key); return <div key={`${condition.label}-${condition.key}`} className="rounded-lg border border-brand-border bg-white p-3"><div className="flex items-center justify-between gap-2"><span className="text-xs font-semibold uppercase tracking-wide text-brand-text-muted">{condition.label}</span><span className={'rounded-full px-2 py-0.5 text-[11px] font-medium ' + (rule?.enabled === false ? 'bg-slate-100 text-slate-600' : 'bg-emerald-100 text-emerald-700')}>{rule?.enabled === false ? 'Desativada' : 'Ativa'}</span></div><strong className="mt-2 block text-sm text-brand-text">{rule?.name || condition.key}</strong><span className="mt-1 block break-words font-mono text-[11px] text-brand-text-muted">{condition.key}</span>{rule?.description && <p className="mt-2 text-xs leading-5 text-brand-text-muted">{rule.description}</p>}<div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-[11px] text-brand-text-muted"><span>Prioridade: {rule?.priority ?? '—'}</span><span>Cooldown: {rule?.cooldown_hours ?? '—'}h</span></div></div>; })}</div>}
                  </div>
                </div>
              </section>

              <div>
                <span className="text-sm font-semibold text-brand-text">Conteúdo do e-mail</span>
                <div className="mt-1 overflow-hidden rounded-lg border border-brand-border focus-within:border-brand-primary">
                  <div className="flex flex-wrap items-center gap-1 border-b border-brand-border bg-brand-bg/60 p-2" role="toolbar" aria-label="Formatação do conteúdo">
                    <button type="button" onMouseDown={(event) => { event.preventDefault(); applyRichTextCommand('bold'); }} className="rounded p-2 text-brand-text-muted hover:bg-white hover:text-brand-primary" title="Negrito"><Bold size={16} /></button>
                    <button type="button" onMouseDown={(event) => { event.preventDefault(); applyRichTextCommand('italic'); }} className="rounded p-2 text-brand-text-muted hover:bg-white hover:text-brand-primary" title="Itálico"><Italic size={16} /></button>
                    <button type="button" onMouseDown={(event) => { event.preventDefault(); applyRichTextCommand('formatBlock', 'h2'); }} className="rounded p-2 text-brand-text-muted hover:bg-white hover:text-brand-primary" title="Título"><Heading2 size={16} /></button>
                    <button type="button" onMouseDown={(event) => { event.preventDefault(); applyRichTextCommand('insertUnorderedList'); }} className="rounded p-2 text-brand-text-muted hover:bg-white hover:text-brand-primary" title="Lista"><List size={16} /></button>
                    <button type="button" onMouseDown={(event) => { event.preventDefault(); applyRichTextCommand('removeFormat'); }} className="rounded p-2 text-brand-text-muted hover:bg-white hover:text-brand-primary" title="Limpar formatação"><Eraser size={16} /></button>
                  </div>
                  <div ref={richTextEditorRef} contentEditable suppressContentEditableWarning onInput={syncRichTextDraft} className="min-h-[280px] max-h-[48vh] overflow-y-auto px-4 py-3 text-sm leading-7 text-brand-text focus:outline-none [&_h1]:mb-3 [&_h1]:text-xl [&_h1]:font-bold [&_h2]:mb-3 [&_h2]:text-lg [&_h2]:font-bold [&_h3]:mb-2 [&_h3]:font-bold [&_li]:ml-5 [&_li]:list-disc [&_p]:mb-3" />
                </div>
                <p className="mt-1.5 text-xs text-brand-text-muted">Use a barra acima para formatar. Variáveis da jornada, como <code>{'{{primeiro_nome}}'}</code>, continuam disponíveis.</p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <label className="block"><span className="text-sm font-semibold text-brand-text">Texto do botão</span><input value={templateDraft.cta_label_template} onChange={(event) => setTemplateDraft({ ...templateDraft, cta_label_template: event.target.value })} className="mt-1 w-full rounded-lg border border-brand-border px-3 py-2.5 text-sm focus:border-brand-primary focus:outline-none" /></label>
                <label className="block"><span className="text-sm font-semibold text-brand-text">Categoria</span><select value={templateDraft.category} onChange={(event) => setTemplateDraft({ ...templateDraft, category: event.target.value })} className="mt-1 w-full rounded-lg border border-brand-border bg-white px-3 py-2.5 text-sm focus:border-brand-primary focus:outline-none">{templateDraft.category && !CATEGORY_LABELS[templateDraft.category] && <option value={templateDraft.category}>{templateDraft.category}</option>}{Object.entries(CATEGORY_LABELS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
                <label className="block"><span className="text-sm font-semibold text-brand-text">Rota principal do botão</span><input value={templateDraft.cta_route_template} onChange={(event) => setTemplateDraft({ ...templateDraft, cta_route_template: event.target.value })} placeholder="/painel/dashboard" className="mt-1 w-full rounded-lg border border-brand-border px-3 py-2.5 text-sm focus:border-brand-primary focus:outline-none" /></label>
                <label className="block"><span className="text-sm font-semibold text-brand-text">Rota alternativa</span><input value={templateDraft.fallback_cta_route} onChange={(event) => setTemplateDraft({ ...templateDraft, fallback_cta_route: event.target.value })} placeholder="/painel/dashboard" className="mt-1 w-full rounded-lg border border-brand-border px-3 py-2.5 text-sm focus:border-brand-primary focus:outline-none" /></label>
              </div>
            </div>

            <div className="flex flex-wrap items-center justify-end gap-2 border-t border-brand-border bg-slate-50/50 p-4 md:p-5">{editingConditions.length > 0 && <>{testStepMessage && <span role="status" className={'mr-auto text-xs ' + (testStepMessage.startsWith('Falha') || testStepMessage.startsWith('Não') ? 'text-red-700' : 'text-emerald-700')}>{testStepMessage}</span>}<button type="button" onClick={() => void sendTestStep()} disabled={templateSaving || sendingTestStepId === editingTemplate.id} className="btn-outline inline-flex items-center gap-2 text-sm">{sendingTestStepId === editingTemplate.id ? <Loader2 size={15} className="animate-spin" /> : <Send size={15} />}{sendingTestStepId === editingTemplate.id ? 'Enviando teste...' : 'Enviar teste ao admin'}</button></>}<button type="button" onClick={cancelTemplateEdit} disabled={templateSaving || Boolean(sendingTestStepId)} className="btn-outline text-sm">Cancelar</button><button type="submit" disabled={templateSaving || Boolean(sendingTestStepId)} className="btn-primary inline-flex items-center gap-2 text-sm">{templateSaving ? <Loader2 size={15} className="animate-spin" /> : <Save size={15} />}{templateSaving ? 'Salvando...' : 'Salvar modelo'}</button></div>
          </form>
        </div>}
      </div>}

      {campaignTab === 'instances' && <div className="overflow-x-auto rounded-xl border border-brand-border bg-white">{users.length === 0 ? <EmptyState icon={Users} title="Nenhum usuário no fluxo" description="Os usuários matriculados em campanhas aparecerão aqui." /> : <table className="w-full min-w-[980px] text-left text-sm"><thead className="bg-brand-bg text-xs uppercase text-brand-text-muted"><tr><th className="p-3">Usuário</th><th className="p-3">Estágio</th><th className="p-3">Passo atual</th><th className="p-3">Próxima execução</th><th className="p-3">Status da jornada</th><th className="p-3">Ações</th></tr></thead><tbody className="divide-y divide-brand-border">{users.map((user) => { const enrollment = activationCampaign ? user.enrollments?.find((item: any) => item.campaign_id === activationCampaign.id) : null; const currentPosition = Number(enrollment?.current_position || 0); const currentStep = activationSteps.find((step) => step.position === currentPosition + 1); const nextStep = activationSteps.find((step) => step.position === currentPosition + 2); const canForceSend = Boolean(enrollment?.status === 'active' && currentStep); const isSending = sendingUserId === user.id; const isRestarting = restartingUserId === user.id; return <tr key={user.id} className="hover:bg-brand-bg/40"><td className="p-3"><strong>{user.full_name || 'Profissional'}</strong><span className="block text-xs text-brand-text-muted">{user.google_email}</span></td><td className="p-3">{activationStatusLabel(user.state?.activation_status)}<span className="block text-xs text-brand-text-muted">Nível {user.state?.activation_level ?? 0}</span></td><td className="p-3">{enrollment ? <><strong className="block">{currentStep ? `Passo ${currentStep.position}` : 'Jornada concluída'}</strong><span className="block max-w-[260px] truncate text-xs text-brand-text-muted">{currentStep?.subject_template || 'Nenhum passo configurado'}</span></> : <span className="text-brand-text-muted">Não matriculado</span>}</td><td className="p-3 whitespace-nowrap">{enrollment ? <><strong className="block">{formatNextExecution(enrollment.next_step_at)}</strong><span className="block text-xs text-brand-text-muted">{nextStep ? `Próximo: passo ${nextStep.position}` : 'Sem próximo passo'}</span></> : '—'}</td><td className="p-3"><span className={'inline-flex rounded-full px-2.5 py-1 text-xs font-medium ' + enrollmentStatusClass(enrollment?.status)}>{enrollmentStatusLabel(enrollment?.status)}</span></td><td className="p-3"><div className="flex flex-wrap gap-1"><button title="Enviar mensagem do passo atual pelos canais habilitados" aria-label="Enviar mensagem do passo atual pelos canais habilitados" disabled={!canForceSend || isSending || isRestarting} onClick={() => void forceSendCurrentStep(user, currentStep)} className="btn-outline inline-flex items-center gap-1.5 p-1.5 text-xs disabled:cursor-not-allowed disabled:opacity-50">{isSending ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />}<span className="sr-only">Enviar agora</span></button><button title="Recalcular" onClick={() => void userAction(user, 'recalculate')} disabled={isRestarting} className="btn-outline p-1.5 disabled:cursor-not-allowed disabled:opacity-50"><RefreshCw size={14} /></button>{enrollment?.status === 'active' ? <button title="Pausar" onClick={() => void userAction(user, 'pause')} disabled={isRestarting} className="btn-outline p-1.5 disabled:cursor-not-allowed disabled:opacity-50"><CirclePause size={14} /></button> : <button title="Matricular/retomar" onClick={() => void userAction(user, enrollment?.status === 'paused' ? 'resume' : 'enroll')} disabled={isRestarting} className="btn-outline p-1.5 disabled:cursor-not-allowed disabled:opacity-50"><CirclePlay size={14} /></button>}<button title="Reiniciar jornada desde o primeiro passo" aria-label="Reiniciar jornada desde o primeiro passo" onClick={() => void restartJourney(user)} disabled={isRestarting} className="btn-outline inline-flex items-center gap-1.5 p-1.5 text-xs disabled:cursor-not-allowed disabled:opacity-50">{isRestarting ? <Loader2 size={14} className="animate-spin" /> : <RotateCcw size={14} />}<span className="sr-only">Reiniciar jornada</span></button></div></td></tr>; })}</tbody></table>}</div>}

      {campaignTab === 'logs' && <LifecycleDeliveryLogs deliveries={deliveries} resendingDispatchId={resendingDispatchId} onResend={(delivery) => void resendLifecycleDelivery(delivery)} />}
    </div>}

    {tab === 'preferences' && <div className="overflow-x-auto rounded-xl border border-brand-border bg-white"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-brand-bg text-xs uppercase text-brand-text-muted"><tr><th className="p-3">Usuário</th><th className="p-3">Jornada</th><th className="p-3">Educativo</th><th className="p-3">Comercial</th><th className="p-3">Atualizado</th></tr></thead><tbody className="divide-y divide-brand-border">{preferences.map((item) => <tr key={item.user_id}><td className="p-3"><strong className="block">{item.user?.full_name || 'Usuário não identificado'}</strong><span className="block text-xs text-brand-text-muted">{item.user?.google_email || item.user_id}</span></td><td className="p-3">{item.lifecycle_enabled ? 'Ativo' : 'Descadastrado'}</td><td className="p-3">{item.product_education_enabled ? 'Sim' : 'Não'}</td><td className="p-3">{item.commercial_enabled ? 'Sim' : 'Não'}</td><td className="p-3">{item.updated_at ? new Date(item.updated_at).toLocaleString('pt-BR') : '—'}</td></tr>)}</tbody></table></div>}

    {tab === 'settings' && <div className="max-w-xl bg-white border border-brand-border rounded-xl p-5 space-y-5"><div className="flex items-center gap-2"><Settings size={18} className="text-brand-primary" /><h3 className="font-semibold">Configurações de publicação</h3></div><label className="flex items-center justify-between gap-4"><span><strong className="block">Simulação / observação</strong><small className="text-brand-text-muted">Calcula decisões, mas não entrega mensagens.</small></span><input type="checkbox" className="h-5 w-5 accent-brand-primary" checked={runtime.dry_run} onChange={(event) => setRuntime({ ...runtime, dry_run: event.target.checked })} /></label><label className="flex items-center justify-between gap-4"><span><strong className="block">Permitir envio real</strong><small className="text-brand-text-muted">Exige campanhas e passos ativos.</small></span><input type="checkbox" className="h-5 w-5 accent-brand-primary" checked={runtime.send_enabled} onChange={(event) => setRuntime({ ...runtime, send_enabled: event.target.checked })} /></label><label className="flex items-center justify-between gap-4 rounded-xl border border-red-200 bg-red-50 p-3"><span><strong className="block text-red-900">Indisponibilidade geral conhecida</strong><small className="text-red-800/80">Impede o alerta de evolução pendente enquanto houver uma falha geral.</small></span><input type="checkbox" className="h-5 w-5 accent-red-600" checked={runtime.global_outage === true} onChange={(event) => setRuntime({ ...runtime, global_outage: event.target.checked })} /></label><label className="block"><span className="text-sm font-semibold">Tamanho do lote</span><input type="number" min={1} max={100} value={runtime.max_batch_size} onChange={(event) => setRuntime({ ...runtime, max_batch_size: Number(event.target.value) })} className="mt-1 w-full rounded-lg border border-brand-border px-3 py-2" /></label><label className="block"><span className="text-sm font-semibold">E-mail para testes condicionais</span><input type="email" value={runtime.test_recipient_email} onChange={(event) => setRuntime({ ...runtime, test_recipient_email: event.target.value })} placeholder="seu-email@dominio.com" className="mt-1 w-full rounded-lg border border-brand-border px-3 py-2" /><small className="mt-1 block text-xs text-brand-text-muted">O botão “Enviar teste ao admin” usará este endereço.</small></label><button onClick={() => void saveRuntime()} className="btn-primary inline-flex items-center gap-2"><Save size={16} /> Salvar configuração</button><p className="text-xs text-amber-700 bg-amber-50 rounded-lg p-3">Ative o envio somente após validar links, planos, modelos, preferências e uma coorte interna.</p></div>}
  </div>;
}

src/components/admin/ManualPushNotificat:
import React, { useEffect, useMemo, useState } from 'react';
import { ChevronDown, ChevronLeft, ChevronRight, Clock, Loader2, Pencil, RefreshCw, Trash2 } from 'lucide-react';

type ManualPushNotification = {
  id: string;
  user_id?: string | null;
  title?: string | null;
  message?: string | null;
  type?: 'info' | 'success' | 'warning' | 'error' | string | null;
  read_at?: string | null;
  created_at?: string | null;
  image_url?: string | null;
  link?: string | null;
  audience_segment?: unknown;
  professionals?: {
    full_name?: string | null;
    google_email?: string | null;
  } | null;
};

type Props = {
  notifications: ManualPushNotification[];
  loading: boolean;
  deletingNotificationId: string | null;
  resendingNotificationId: string | null;
  getAudienceLabel: (notification: ManualPushNotification) => string;
  onClear: () => void;
  onCopy: (notification: ManualPushNotification) => void;
  onResend: (notification: ManualPushNotification) => void;
  onDelete: (notificationId: string) => void;
};

const GROUPS_PER_PAGE = 10;

const formatDateTime = (value?: string | null) => {
  if (!value) return 'N/A';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return 'N/A';
  return date.toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
};

const notificationGroupKey = (notification: ManualPushNotification) => JSON.stringify([
  String(notification.title || '').trim(),
  String(notification.message || '').trim(),
]);

export default function ManualPushNotificationHistory({
  notifications,
  loading,
  deletingNotificationId,
  resendingNotificationId,
  getAudienceLabel,
  onClear,
  onCopy,
  onResend,
  onDelete,
}: Props) {
  const [page, setPage] = useState(1);
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(() => new Set());

  const groups = useMemo(() => {
    const grouped = new Map<string, {
      key: string;
      title: string;
      message: string;
      latestAt: number;
      latestCreatedAt: string | null;
      imageUrl: string | null;
      notifications: ManualPushNotification[];
    }>();

    notifications.forEach((notification) => {
      const key = notificationGroupKey(notification);
      const createdAt = notification.created_at ? new Date(notification.created_at).getTime() : 0;
      const current = grouped.get(key);
      if (current) {
        current.notifications.push(notification);
        if (createdAt > current.latestAt) {
          current.latestAt = createdAt;
          current.latestCreatedAt = notification.created_at || null;
          current.imageUrl = notification.image_url || current.imageUrl;
        }
        return;
      }

      grouped.set(key, {
        key,
        title: String(notification.title || 'Sem título'),
        message: String(notification.message || ''),
        latestAt: Number.isFinite(createdAt) ? createdAt : 0,
        latestCreatedAt: notification.created_at || null,
        imageUrl: notification.image_url || null,
        notifications: [notification],
      });
    });

    return Array.from(grouped.values())
      .map((group) => ({
        ...group,
        notifications: [...group.notifications].sort((left, right) => {
          const leftTime = left.created_at ? new Date(left.created_at).getTime() : 0;
          const rightTime = right.created_at ? new Date(right.created_at).getTime() : 0;
          return rightTime - leftTime;
        }),
      }))
      .sort((left, right) => right.latestAt - left.latestAt);
  }, [notifications]);

  const totalPages = Math.max(1, Math.ceil(groups.length / GROUPS_PER_PAGE));
  const pageGroups = groups.slice((page - 1) * GROUPS_PER_PAGE, page * GROUPS_PER_PAGE);

  useEffect(() => {
    setPage((current) => Math.min(current, totalPages));
  }, [totalPages]);

  const goToPage = (nextPage: number) => {
    const safePage = Math.min(Math.max(1, nextPage), totalPages);
    setPage(safePage);
    setExpandedGroups(new Set());
  };

  const toggleGroup = (key: string) => {
    setExpandedGroups((current) => {
      const next = new Set(current);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  return (
    <div className="card p-6 bg-white shadow-sm border border-brand-border/60">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-4">
        <div>
          <h3 className="text-lg font-semibold text-brand-text flex items-center space-x-2">
            <Clock size={18} className="text-brand-primary" />
            <span>Notificações push enviadas manualmente</span>
          </h3>
          {!loading && groups.length > 0 && (
            <p className="mt-1 text-xs text-brand-text-muted">
              {groups.length} grupo{groups.length === 1 ? '' : 's'} por título / mensagem · {notifications.length} envio{notifications.length === 1 ? '' : 's'}
            </p>
          )}
        </div>
        <button
          type="button"
          onClick={onClear}
          disabled={notifications.length === 0 || loading}
          className="inline-flex items-center justify-center gap-2 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-xs font-semibold text-red-700 transition-colors hover:bg-red-100 disabled:cursor-not-allowed disabled:opacity-50"
        >
          <Trash2 size={14} />
          <span>Limpar histórico</span>
        </button>
      </div>

      {loading ? (
        <div className="p-12 flex flex-col items-center justify-center text-brand-text-muted">
          <Loader2 className="w-8 h-8 text-brand-primary animate-spin mb-3" />
          <span className="text-sm">Carregando logs...</span>
        </div>
      ) : notifications.length === 0 ? (
        <div className="p-12 text-center text-brand-text-muted text-sm italic">
          Nenhuma notificação manual cadastrada no sistema.
        </div>
      ) : (
        <div className="space-y-3">
          {pageGroups.map((group) => {
            const expanded = expandedGroups.has(group.key);
            return (
              <div key={group.key} className="overflow-hidden rounded-2xl border border-brand-border/60 bg-white">
                <button
                  type="button"
                  onClick={() => toggleGroup(group.key)}
                  aria-expanded={expanded}
                  className="flex w-full items-start gap-3 p-4 text-left transition-colors hover:bg-brand-bg/20"
                >
                  {group.imageUrl && (
                    <img
                      src={group.imageUrl}
                      alt="Capa"
                      className="h-10 w-10 shrink-0 rounded-lg border border-brand-border/40 object-cover"
                    />
                  )}
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div className="min-w-0">
                        <p className="font-semibold text-sm text-brand-text">{group.title}</p>
                        <p className="mt-0.5 line-clamp-2 text-xs leading-relaxed text-brand-text-muted">{group.message || 'Sem mensagem'}</p>
                      </div>
                      <div className="flex shrink-0 items-center gap-2">
                        <span className="rounded-full border border-brand-primary/15 bg-brand-primary/5 px-2 py-1 text-[10px] font-bold text-brand-primary">
                          {group.notifications.length} registro{group.notifications.length === 1 ? '' : 's'}
                        </span>
                        <ChevronDown size={17} className={`text-brand-text-muted transition-transform ${expanded ? 'rotate-180' : ''}`} />
                      </div>
                    </div>
                    <p className="mt-2 text-[10px] text-brand-text-muted">
                      Último envio: {formatDateTime(group.latestCreatedAt)}
                    </p>
                  </div>
                </button>

                {expanded && (
                  <div className="border-t border-brand-border/50 overflow-x-auto">
                    <table className="w-full min-w-[920px] text-left text-sm border-collapse">
                      <thead>
                        <tr className="border-b border-brand-border/60 bg-brand-bg/20 text-brand-text font-bold text-xs uppercase tracking-wider">
                          <th className="py-2.5 px-3">Profissional</th>
                          <th className="py-2.5 px-3">Segmentação utilizada</th>
                          <th className="py-2.5 px-3">Tipo</th>
                          <th className="py-2.5 px-3">Lido em</th>
                          <th className="py-2.5 px-3">Enviado em</th>
                          <th className="py-2.5 px-3 text-right">Ação</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-brand-border/30 text-xs">
                        {group.notifications.map((notification) => (
                          <tr key={notification.id} className="hover:bg-brand-bg/10 transition-colors">
                            <td className="py-2.5 px-3">
                              <p className="font-semibold text-brand-text">{notification.professionals?.full_name || 'Profissional'}</p>
                              <p className="text-[10px] text-brand-text-muted">{notification.professionals?.google_email || ''}</p>
                            </td>
                            <td className="py-2.5 px-3 min-w-[180px]">
                              <span className="inline-flex rounded-full border border-brand-primary/20 bg-brand-primary/5 px-2 py-1 text-[10px] font-semibold text-brand-primary">
                                {getAudienceLabel(notification)}
                              </span>
                            </td>
                            <td className="py-2.5 px-3">
                              <span className={`inline-block px-2 py-0.5 rounded-full text-[9px] font-bold uppercase ${
                                notification.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-150' :
                                notification.type === 'error' ? 'bg-red-50 text-red-700 border border-red-150' :
                                notification.type === 'warning' ? 'bg-amber-50 text-amber-700 border border-amber-150' :
                                'bg-blue-50 text-blue-700 border border-blue-150'
                              }`}>
                                {notification.type || 'info'}
                              </span>
                            </td>
                            <td className="py-2.5 px-3 text-brand-text-muted">
                              {notification.read_at ? formatDateTime(notification.read_at) : (
                                <span className="text-[10px] text-red-500 font-semibold uppercase">Não lido</span>
                              )}
                            </td>
                            <td className="py-2.5 px-3 text-brand-text-muted">{formatDateTime(notification.created_at)}</td>
                            <td className="py-2.5 px-3 text-right">
                              <button
                                type="button"
                                onClick={() => onCopy(notification)}
                                className="p-1 text-brand-primary hover:bg-brand-bg rounded transition-colors mr-1 cursor-pointer"
                                title="Editar conteúdo e preparar novo envio"
                              >
                                <Pencil size={15} />
                              </button>
                              <button
                                type="button"
                                onClick={() => onResend(notification)}
                                disabled={resendingNotificationId === notification.id}
                                className="p-1 text-emerald-600 hover:bg-emerald-50 rounded transition-colors mr-1 disabled:opacity-50 cursor-pointer"
                                title="Reenviar Notificação Imediatamente"
                              >
                                {resendingNotificationId === notification.id ? <Loader2 className="animate-spin" size={15} /> : <RefreshCw size={15} />}
                              </button>
                              <button
                                type="button"
                                onClick={() => onDelete(notification.id)}
                                disabled={deletingNotificationId === notification.id}
                                className="p-1 text-red-500 hover:bg-red-50 rounded transition-colors disabled:opacity-50 cursor-pointer"
                                title="Excluir registro"
                              >
                                {deletingNotificationId === notification.id ? <Loader2 className="animate-spin" size={15} /> : <Trash2 size={15} />}
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            );
          })}

          {totalPages > 1 && (
            <div className="flex flex-col gap-2 border-t border-brand-border/40 pt-4 sm:flex-row sm:items-center sm:justify-between">
              <p className="text-xs text-brand-text-muted">
                Página {page} de {totalPages} · até {GROUPS_PER_PAGE} grupos por página
              </p>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => goToPage(page - 1)}
                  disabled={page <= 1}
                  className="inline-flex items-center gap-1 rounded-xl border border-brand-border bg-white px-3 py-2 text-xs font-semibold text-brand-text transition-colors hover:border-brand-primary/40 disabled:cursor-not-allowed disabled:opacity-40"
                >
                  <ChevronLeft size={14} />Anterior
                </button>
                <button
                  type="button"
                  onClick={() => goToPage(page + 1)}
                  disabled={page >= totalPages}
                  className="inline-flex items-center gap-1 rounded-xl border border-brand-border bg-white px-3 py-2 text-xs font-semibold text-brand-text transition-colors hover:border-brand-primary/40 disabled:cursor-not-allowed disabled:opacity-40"
                >
                  Próxima<ChevronRight size={14} />
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

