import { useEffect, useState, type ReactNode } from 'react';
import {
  Briefcase,
  Bell,
  Calendar,
  CheckCircle2,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Clock3,
  CreditCard,
  Database,
  FileText,
  Loader2,
  Globe,
  History,
  Mail,
  MessageCircle,
  RefreshCw,
  Sparkles,
  User,
  Users,
  X,
  XCircle,
  type LucideIcon
} from 'lucide-react';
import { supabase } from '../../supabaseClient';
import {
  getAcquisitionChannelLabel,
  getAcquisitionDistribution,
  getAcquisitionPlatform,
  isTechnicalPlatformMarker,
  type AcquisitionData
} from '../../utils/acquisitionAttribution';
import { getSubscriptionPlanLabel } from '../../utils/subscriptionPlans';

type ProfessionalSummary = {
  id: string;
  full_name: string;
  google_email: string;
};

type ProfessionalDetails = {
  professional: Record<string, any>;
  communicationPreferences: Record<string, any> | null;
  onboardingEligibility: {
    evaluatedAt: string;
    blockedReason: string | null;
    emails: Array<{
      key: string;
      subject: string;
      campaignName: string;
      stepPosition: number;
      kind: 'sequence' | 'conditional';
      status: 'eligible' | 'scheduled' | 'waiting';
      scheduledFor: string | null;
      reason: string;
    }>;
  };
  clinicalMetrics: {
    patientCount: number;
    evolutionCount: number;
    transcribedSeconds: number;
    patients: Array<{
      id: string;
      name: string;
      status: string | null;
      evolutionCount: number;
      transcribedSeconds: number;
    }>;
  };
  auth: {
    created_at: string | null;
    last_sign_in_at: string | null;
    email_confirmed_at: string | null;
  } | null;
};

type CommunicationChannel = 'all' | 'email' | 'notification' | 'whatsapp';

type CommunicationHistoryItem = {
  id: string;
  channel: Exclude<CommunicationChannel, 'all'>;
  title: string;
  message: string;
  status: string;
  source: string | null;
  createdAt: string;
  readAt: string | null;
  deliveredAt: string | null;
  errorMessage: string | null;
  metadata: {
    provider?: string | null;
    recipient?: string | null;
    messageType?: string | null;
    templateName?: string | null;
    attemptCount?: number | null;
    link?: string | null;
  };
};

type CommunicationHistory = {
  items: CommunicationHistoryItem[];
  counts: Record<CommunicationChannel, number>;
  pagination: {
    page: number;
    pageSize: number;
    total: number;
    totalPages: number;
  };
};

type Props = {
  professional: ProfessionalSummary | null;
  onClose: () => void;
};

const dateValue = (value: unknown) => {
  if (!value) return 'Não informado';
  const parsed = new Date(String(value));
  return Number.isNaN(parsed.getTime()) ? String(value) : parsed.toLocaleString('pt-BR');
};

const textValue = (value: unknown) => {
  if (value === null || value === undefined || value === '') return 'Não informado';
  if (typeof value === 'boolean') return value ? 'Sim' : 'Não';
  return String(value);
};

const Detail = ({ label, value, mono = false }: { label: string; value: unknown; mono?: boolean }) => (
  <div className="rounded-xl border border-brand-border/50 bg-brand-bg/30 p-3">
    <span className="block text-[10px] font-bold uppercase tracking-wider text-brand-text-muted">{label}</span>
    <span className={`mt-1 block break-words text-sm font-semibold text-brand-text ${mono ? 'font-mono text-xs' : ''}`}>
      {textValue(value)}
    </span>
  </div>
);

const Section = ({ icon: Icon, title, children }: { icon: LucideIcon; title: string; children: ReactNode }) => (
  <section className="space-y-3">
    <h4 className="flex items-center gap-2 border-b border-brand-border/40 pb-2 text-xs font-bold uppercase tracking-wider text-brand-primary">
      <Icon className="h-4 w-4" />
      {title}
    </h4>
    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">{children}</div>
  </section>
);

const HISTORY_PAGE_SIZE = 10;
const COMMUNICATION_CHANNELS: { key: CommunicationChannel; label: string; icon: LucideIcon }[] = [
  { key: 'all', label: 'Todos', icon: History },
  { key: 'email', label: 'E-mails', icon: Mail },
  { key: 'notification', label: 'Notificações', icon: Bell },
  { key: 'whatsapp', label: 'WhatsApp', icon: MessageCircle }
];

const channelPresentation = (channel: CommunicationHistoryItem['channel']) => {
  if (channel === 'email') return { label: 'E-mail', icon: Mail, className: 'bg-sky-50 text-sky-700 border-sky-200' };
  if (channel === 'notification') return { label: 'Notificação', icon: Bell, className: 'bg-violet-50 text-violet-700 border-violet-200' };
  return { label: 'WhatsApp', icon: MessageCircle, className: 'bg-emerald-50 text-emerald-700 border-emerald-200' };
};

const platformLabel = (data: AcquisitionData) => {
  const platform = getAcquisitionPlatform(data);
  if (platform === 'android') return 'Android';
  if (platform === 'pwa') return 'PWA';
  if (platform === 'web') return 'Web';
  return null;
};

const distributionLabel = (data: AcquisitionData) => (
  getAcquisitionDistribution(data) === 'google_play' ? 'Google Play' : null
);

const marketingValue = (value?: string) => isTechnicalPlatformMarker(value) ? null : value;
const clickIdStatus = (value?: string) => value ? 'Capturado' : 'Não capturado';

const statusPresentation = (status: string) => {
  const normalized = status.toLowerCase();
  const labels: Record<string, string> = {
    available: 'Disponível no app',
    sent: 'Enviado',
    delivered: 'Entregue',
    read: 'Lido',
    accepted: 'Aceito pela Meta',
    pending: 'Pendente',
    failed: 'Falhou'
  };
  const className = normalized === 'failed'
    ? 'bg-red-50 text-red-700 border-red-200'
    : normalized === 'pending' || normalized === 'accepted'
      ? 'bg-amber-50 text-amber-700 border-amber-200'
      : 'bg-emerald-50 text-emerald-700 border-emerald-200';
  return { label: labels[normalized] || status, className };
};

const formatTranscribedMinutes = (secondsValue: unknown) => {
  const seconds = Number(secondsValue || 0);
  if (!Number.isFinite(seconds) || seconds <= 0) return '0 min';
  const minutes = seconds / 60;
  if (minutes < 1) return '< 1 min';
  return `${new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 1 }).format(minutes)} min`;
};

const eligibilityPresentation = (status: 'eligible' | 'scheduled' | 'waiting') => {
  if (status === 'scheduled') return { label: 'Agendado', className: 'border-sky-200 bg-sky-50 text-sky-700' };
  if (status === 'waiting') return { label: 'Aguardando', className: 'border-amber-200 bg-amber-50 text-amber-700' };
  return { label: 'Elegível agora', className: 'border-emerald-200 bg-emerald-50 text-emerald-700' };
};

const patientStatusLabel = (status: string | null) => {
  if (status === 'active') return 'Ativo';
  if (status === 'inactive') return 'Inativo';
  if (status === 'archived') return 'Arquivado';
  return status || 'Sem status';
};

export default function ProfessionalDetailsModal({ professional, onClose }: Props) {
  const [details, setDetails] = useState<ProfessionalDetails | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [communicationChannel, setCommunicationChannel] = useState<CommunicationChannel>('all');
  const [communicationExpanded, setCommunicationExpanded] = useState(false);
  const [communicationPage, setCommunicationPage] = useState(1);
  const [communicationHistory, setCommunicationHistory] = useState<CommunicationHistory | null>(null);
  const [communicationLoading, setCommunicationLoading] = useState(false);
  const [communicationError, setCommunicationError] = useState('');
  const [communicationReloadKey, setCommunicationReloadKey] = useState(0);

  useEffect(() => {
    if (!professional) return;
    let active = true;

    const load = async () => {
      setLoading(true);
      setError('');
      setDetails(null);
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        const token = sessionData.session?.access_token;
        if (!token) throw new Error('Sessão administrativa não encontrada.');

        const response = await fetch(`/api/admin/professionals/${professional.id}/details`, {
          cache: 'no-store',
          headers: { Authorization: `Bearer ${token}` }
        });
        const payload = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(payload.error || 'Não foi possível carregar os dados do profissional.');
        if (active) setDetails(payload);
      } catch (loadError: any) {
        if (active) setError(loadError.message || 'Não foi possível carregar os dados do profissional.');
      } finally {
        if (active) setLoading(false);
      }
    };

    void load();
    return () => { active = false; };
  }, [professional]);

  useEffect(() => {
    setCommunicationExpanded(false);
    setCommunicationChannel('all');
    setCommunicationPage(1);
    setCommunicationHistory(null);
    setCommunicationError('');
  }, [professional?.id]);

  useEffect(() => {
    if (!professional) return;
    let active = true;

    const loadHistory = async () => {
      setCommunicationLoading(true);
      setCommunicationError('');
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        const token = sessionData.session?.access_token;
        if (!token) throw new Error('Sessão administrativa não encontrada.');
        const params = new URLSearchParams({
          channel: communicationChannel,
          page: String(communicationPage),
          pageSize: String(HISTORY_PAGE_SIZE)
        });
        const response = await fetch(`/api/admin/professionals/${professional.id}/communications?${params}`, {
          cache: 'no-store',
          headers: { Authorization: `Bearer ${token}` }
        });
        const payload = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(payload.error || 'Não foi possível carregar o histórico de comunicação.');
        if (active) setCommunicationHistory(payload);
      } catch (loadError: any) {
        if (active) setCommunicationError(loadError.message || 'Não foi possível carregar o histórico de comunicação.');
      } finally {
        if (active) setCommunicationLoading(false);
      }
    };

    void loadHistory();
    return () => { active = false; };
  }, [professional, communicationChannel, communicationPage, communicationReloadKey]);

  if (!professional) return null;
  const p = details?.professional || {};
  const preferences = details?.communicationPreferences;
  const firstAcquisition = (p.acquisition_info || {}) as AcquisitionData;
  const signupAcquisition = (p.signup_acquisition_info || {}) as AcquisitionData;

  return (
    <div className="fixed inset-0 z-[90] flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm animate-fadeIn" role="dialog" aria-modal="true" aria-labelledby="professional-details-title">
      <div className="flex max-h-[92vh] w-full max-w-5xl flex-col overflow-hidden rounded-3xl border border-brand-border/60 bg-white shadow-2xl">
        <header className="flex items-center justify-between border-b border-brand-border/50 bg-gradient-to-r from-brand-primary/10 to-brand-accent/10 px-5 py-4 sm:px-6">
          <div className="flex min-w-0 items-center gap-3">
            <div className="rounded-xl bg-brand-primary p-2.5 text-white"><User className="h-5 w-5" /></div>
            <div className="min-w-0">
              <h3 id="professional-details-title" className="font-display text-base font-bold text-brand-primary">Dados e histórico do profissional</h3>
              <p className="truncate text-xs text-brand-text-muted">{professional.full_name} ({professional.google_email})</p>
            </div>
          </div>
          <button type="button" onClick={onClose} className="rounded-lg p-2 text-brand-text-muted transition-colors hover:bg-black/5 hover:text-brand-text" aria-label="Fechar detalhes">
            <X className="h-5 w-5" />
          </button>
        </header>

        <div className="flex-1 space-y-6 overflow-y-auto p-5 sm:p-6">
          {loading ? (
            <div className="flex min-h-64 flex-col items-center justify-center gap-3 text-brand-text-muted">
              <Loader2 className="h-8 w-8 animate-spin text-brand-primary" />
              <span className="text-sm">Carregando informações...</span>
            </div>
          ) : error ? (
            <div className="rounded-2xl border border-red-200 bg-red-50 p-5 text-sm text-red-700">{error}</div>
          ) : details ? (
            <>
              <Section icon={User} title="Identificação">
                <Detail label="Nome completo" value={p.full_name} />
                <Detail label="E-mail" value={p.google_email} />
                <Detail label="ID do usuário" value={p.id} mono />
                <Detail label="Perfil de acesso" value={p.role === 'admin' ? 'Administrador' : 'Profissional'} />
                <Detail label="Status" value={p.status} />
              <Detail label="Onboarding concluído" value={p.onboarding_completed} />
              <Detail
                label="Status do onboarding"
                value={{
                  not_started: 'Não iniciado',
                  in_progress: 'Em andamento',
                  deferred: 'Explorando o aplicativo',
                  completed: 'Concluído',
                }[String(p.onboarding_status || '')] || 'Não informado'}
              />
              <Detail
                label="Caminho inicial escolhido"
                value={p.onboarding_initial_mode === 'guided' ? 'Configurar com ajuda' : p.onboarding_initial_mode === 'explore' ? 'Conhecer o aplicativo primeiro' : 'Não registrado'}
              />
              <Detail
                label="Modo atual do onboarding"
                value={p.onboarding_mode === 'guided' ? 'Configuração guiada' : p.onboarding_mode === 'explore' ? 'Explorando o aplicativo' : 'Não escolhido'}
              />
              <Detail label="Escolha registrada em" value={dateValue(p.onboarding_choice_at)} />
              <Detail
                label="Etapa atual"
                value={{
                  intro: 'Apresentação',
                  patient: 'Primeiro paciente e prontuário',
                  evolution: 'Primeira evolução',
                  agenda: 'Google Agenda (opcional)',
                  complete: 'Concluído',
                }[String(p.onboarding_current_step || '')] || 'Não informada'}
              />
              </Section>

              <section className="space-y-3" data-testid="professional-onboarding-eligibility">
                <div className="border-b border-brand-border/40 pb-2">
                  <h4 className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-brand-primary">
                    <Sparkles className="h-4 w-4" />
                    Elegível para os e-mails
                  </h4>
                  <p className="mt-1 text-xs text-brand-text-muted">Modelos do onboarding que podem ser enviados conforme o estado atual do profissional.</p>
                </div>

                {details.onboardingEligibility.emails.length ? (
                  <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                    {details.onboardingEligibility.emails.map(email => {
                      const presentation = eligibilityPresentation(email.status);
                      return (
                        <article key={email.key} className="rounded-2xl border border-brand-border/60 bg-brand-bg/20 p-4">
                          <div className="flex flex-wrap items-center justify-between gap-2">
                            <span className="text-[10px] font-bold uppercase tracking-wide text-brand-primary">
                              Passo {email.stepPosition} · {email.kind === 'conditional' ? 'Condicional' : 'Jornada'}
                            </span>
                            <span className={`rounded-full border px-2 py-1 text-[10px] font-bold ${presentation.className}`}>{presentation.label}</span>
                          </div>
                          <h5 className="mt-2 text-sm font-bold text-brand-text">{email.subject}</h5>
                          <p className="mt-1 text-xs text-brand-text-muted">{email.campaignName} · {email.reason}</p>
                          {email.scheduledFor && (
                            <p className="mt-2 flex items-center gap-1.5 text-[11px] font-semibold text-brand-text-muted">
                              <Clock3 className="h-3.5 w-3.5" />
                              {email.status === 'scheduled' ? 'Envio previsto' : 'Disponível a partir de'}: {dateValue(email.scheduledFor)}
                            </p>
                          )}
                        </article>
                      );
                    })}
                  </div>
                ) : (
                  <div className="rounded-2xl border border-dashed border-brand-border bg-brand-bg/20 p-4 text-sm text-brand-text-muted">
                    {details.onboardingEligibility.blockedReason || 'Nenhum e-mail elegível neste momento.'}
                  </div>
                )}
              </section>

              <section className="space-y-3" data-testid="professional-clinical-metrics">
                <div className="border-b border-brand-border/40 pb-2">
                  <h4 className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-brand-primary">
                    <Users className="h-4 w-4" />
                    Pacientes e uso clínico
                  </h4>
                  <p className="mt-1 text-xs text-brand-text-muted">Resumo dos pacientes, evoluções registradas e tempo efetivamente transcrito.</p>
                </div>

                <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
                  <div className="rounded-2xl border border-sky-200 bg-sky-50 p-4">
                    <Users className="h-5 w-5 text-sky-700" />
                    <strong className="mt-2 block text-2xl text-sky-950">{details.clinicalMetrics.patientCount}</strong>
                    <span className="text-xs font-semibold text-sky-700">Pacientes</span>
                  </div>
                  <div className="rounded-2xl border border-violet-200 bg-violet-50 p-4">
                    <FileText className="h-5 w-5 text-violet-700" />
                    <strong className="mt-2 block text-2xl text-violet-950">{details.clinicalMetrics.evolutionCount}</strong>
                    <span className="text-xs font-semibold text-violet-700">Evoluções</span>
                  </div>
                  <div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4">
                    <Clock3 className="h-5 w-5 text-emerald-700" />
                    <strong className="mt-2 block text-2xl text-emerald-950">{formatTranscribedMinutes(details.clinicalMetrics.transcribedSeconds)}</strong>
                    <span className="text-xs font-semibold text-emerald-700">Minutos transcritos</span>
                  </div>
                </div>

                {details.clinicalMetrics.patients.length ? (
                  <div className="max-h-72 overflow-auto rounded-2xl border border-brand-border/60">
                    <table className="w-full min-w-[560px] text-left text-xs">
                      <thead className="sticky top-0 bg-brand-bg text-[10px] uppercase tracking-wide text-brand-text-muted">
                        <tr>
                          <th className="px-4 py-3">Paciente</th>
                          <th className="px-4 py-3 text-center">Evoluções</th>
                          <th className="px-4 py-3 text-right">Áudio transcrito</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-brand-border/50 bg-white">
                        {details.clinicalMetrics.patients.map(patient => (
                          <tr key={patient.id}>
                            <td className="px-4 py-3">
                              <strong className="block text-brand-text">{patient.name}</strong>
                              <span className="text-[10px] text-brand-text-muted">{patientStatusLabel(patient.status)}</span>
                            </td>
                            <td className="px-4 py-3 text-center font-bold text-brand-text">{patient.evolutionCount}</td>
                            <td className="px-4 py-3 text-right font-semibold text-brand-text">{formatTranscribedMinutes(patient.transcribedSeconds)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <div className="rounded-2xl border border-dashed border-brand-border bg-brand-bg/20 p-4 text-sm text-brand-text-muted">
                    Este profissional ainda não possui pacientes cadastrados.
                  </div>
                )}
                <p className="text-[11px] text-brand-text-muted">O total usa os registros efetivos de transcrição; a distribuição por paciente considera os áudios vinculados às evoluções.</p>
              </section>

              <section className="space-y-3" data-testid="professional-communication-history">
                <button
                  type="button"
                  onClick={() => setCommunicationExpanded(current => !current)}
                  aria-expanded={communicationExpanded}
                  aria-controls="professional-communication-history-content"
                  className="flex w-full items-center justify-between gap-4 rounded-2xl border border-brand-border/60 bg-brand-bg/20 px-4 py-4 text-left transition-colors hover:border-brand-primary/40 hover:bg-brand-primary/5"
                >
                  <div className="min-w-0">
                    <h4 className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-brand-primary">
                      <History className="h-4 w-4" />
                      Histórico de comunicação
                    </h4>
                    <p className="mt-1 text-xs text-brand-text-muted">Linha do tempo de todos os contatos registrados pela plataforma.</p>
                  </div>
                  <span className="flex shrink-0 items-center gap-2 text-xs font-bold text-brand-primary">
                    {communicationExpanded ? 'Recolher' : 'Expandir'}
                    <ChevronDown className={`h-4 w-4 transition-transform ${communicationExpanded ? 'rotate-180' : ''}`} />
                  </span>
                </button>

                {communicationExpanded && (
                  <div id="professional-communication-history-content" className="space-y-3">
                    <div className="flex justify-end">
                  <button
                    type="button"
                    onClick={() => setCommunicationReloadKey(current => current + 1)}
                    disabled={communicationLoading}
                    className="inline-flex items-center justify-center gap-1.5 self-start rounded-lg border border-brand-border bg-white px-3 py-2 text-xs font-semibold text-brand-text transition-colors hover:border-brand-primary/40 hover:text-brand-primary disabled:opacity-60 sm:self-auto"
                  >
                    <RefreshCw className={`h-3.5 w-3.5 ${communicationLoading ? 'animate-spin' : ''}`} />
                    Atualizar
                  </button>
                    </div>

                    <div className="flex flex-wrap gap-2" aria-label="Filtrar histórico por canal">
                  {COMMUNICATION_CHANNELS.map(({ key, label, icon: Icon }) => {
                    const count = communicationHistory?.counts?.[key] ?? 0;
                    const active = communicationChannel === key;
                    return (
                      <button
                        key={key}
                        type="button"
                        onClick={() => {
                          setCommunicationChannel(key);
                          setCommunicationPage(1);
                        }}
                        aria-pressed={active}
                        className={`inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-xs font-semibold transition-colors ${active
                          ? 'border-brand-primary bg-brand-primary text-white'
                          : 'border-brand-border bg-white text-brand-text hover:border-brand-primary/40 hover:text-brand-primary'
                        }`}
                      >
                        <Icon className="h-3.5 w-3.5" />
                        {label} ({count})
                      </button>
                    );
                  })}
                </div>

                {communicationLoading && !communicationHistory ? (
                  <div className="flex min-h-36 items-center justify-center gap-2 rounded-2xl border border-brand-border/50 bg-brand-bg/20 text-sm text-brand-text-muted">
                    <Loader2 className="h-5 w-5 animate-spin text-brand-primary" />
                    Carregando histórico...
                  </div>
                ) : communicationError ? (
                  <div className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">
                    {communicationError}
                  </div>
                ) : communicationHistory?.items.length ? (
                  <div className={`space-y-3 ${communicationLoading ? 'opacity-60' : ''}`} aria-busy={communicationLoading}>
                    {communicationHistory.items.map(item => {
                      const channel = channelPresentation(item.channel);
                      const status = statusPresentation(item.status);
                      const ChannelIcon = channel.icon;
                      return (
                        <article key={item.id} className="rounded-2xl border border-brand-border/60 bg-white p-4 shadow-sm">
                          <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
                            <div className="min-w-0">
                              <div className="flex flex-wrap items-center gap-2">
                                <span className={`inline-flex items-center gap-1 rounded-full border px-2 py-1 text-[10px] font-bold uppercase tracking-wide ${channel.className}`}>
                                  <ChannelIcon className="h-3 w-3" />
                                  {channel.label}
                                </span>
                                <span className={`rounded-full border px-2 py-1 text-[10px] font-bold ${status.className}`}>{status.label}</span>
                              </div>
                              <h5 className="mt-2 break-words text-sm font-bold text-brand-text">{item.title}</h5>
                            </div>
                            <time className="shrink-0 text-[11px] font-medium text-brand-text-muted" dateTime={item.createdAt}>
                              {dateValue(item.createdAt)}
                            </time>
                          </div>

                          {item.message && (
                            <p className="mt-2 whitespace-pre-wrap break-words text-xs leading-relaxed text-brand-text-muted">{item.message}</p>
                          )}

                          <div className="mt-3 flex flex-wrap gap-x-4 gap-y-1 border-t border-brand-border/40 pt-3 text-[11px] text-brand-text-muted">
                            {item.source && <span><strong className="text-brand-text">Origem:</strong> {item.source}</span>}
                            {item.metadata.provider && <span><strong className="text-brand-text">Provedor:</strong> {item.metadata.provider}</span>}
                            {item.metadata.recipient && <span><strong className="text-brand-text">Destinatário:</strong> {item.metadata.recipient}</span>}
                            {item.metadata.messageType && <span><strong className="text-brand-text">Tipo:</strong> {item.metadata.messageType}</span>}
                            {item.metadata.attemptCount != null && <span><strong className="text-brand-text">Tentativas:</strong> {item.metadata.attemptCount}</span>}
                            {item.deliveredAt && <span><strong className="text-brand-text">Entrega:</strong> {dateValue(item.deliveredAt)}</span>}
                            {item.readAt && <span><strong className="text-brand-text">Leitura:</strong> {dateValue(item.readAt)}</span>}
                            {item.metadata.link && <span className="break-all"><strong className="text-brand-text">Destino:</strong> {item.metadata.link}</span>}
                          </div>

                          {item.errorMessage && (
                            <p className="mt-3 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
                              <strong>Falha:</strong> {item.errorMessage}
                            </p>
                          )}
                        </article>
                      );
                    })}
                  </div>
                ) : (
                  <div className="rounded-2xl border border-dashed border-brand-border bg-brand-bg/20 p-6 text-center text-sm text-brand-text-muted">
                    Nenhum registro encontrado neste canal.
                  </div>
                )}

                {communicationHistory && communicationHistory.pagination.total > 0 && (
                  <div className="flex flex-col gap-2 rounded-xl bg-brand-bg/30 px-3 py-2 text-xs text-brand-text-muted sm:flex-row sm:items-center sm:justify-between">
                    <span>
                      Página {communicationHistory.pagination.page} de {communicationHistory.pagination.totalPages} · {communicationHistory.pagination.total} registros
                    </span>
                    <div className="flex gap-2">
                      <button
                        type="button"
                        onClick={() => setCommunicationPage(current => Math.max(1, current - 1))}
                        disabled={communicationLoading || communicationPage <= 1}
                        className="inline-flex items-center gap-1 rounded-lg border border-brand-border bg-white px-2.5 py-1.5 font-semibold text-brand-text disabled:cursor-not-allowed disabled:opacity-40"
                      >
                        <ChevronLeft className="h-3.5 w-3.5" />
                        Anterior
                      </button>
                      <button
                        type="button"
                        onClick={() => setCommunicationPage(current => Math.min(communicationHistory.pagination.totalPages, current + 1))}
                        disabled={communicationLoading || communicationPage >= communicationHistory.pagination.totalPages}
                        className="inline-flex items-center gap-1 rounded-lg border border-brand-border bg-white px-2.5 py-1.5 font-semibold text-brand-text disabled:cursor-not-allowed disabled:opacity-40"
                      >
                        Próxima
                        <ChevronRight className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  </div>
                )}

                <p className="text-[11px] text-brand-text-muted">
                  O WhatsApp registra template, status e datas de entrega; o conteúdo completo não é armazenado por segurança.
                </p>
                  </div>
                )}
              </section>

              <Section icon={MessageCircle} title="WhatsApp e comunicação">
                <Detail label="Número do WhatsApp" value={preferences?.whatsapp_number} />
                <Detail label="WhatsApp verificado" value={preferences?.whatsapp_verified_number ? 'Sim' : 'Não'} />
                <Detail label="Verificado em" value={dateValue(preferences?.whatsapp_verified_at)} />
                <Detail label="Autorizou mensagens" value={preferences?.whatsapp_opt_in} />
                <Detail label="WhatsApp habilitado" value={preferences?.whatsapp_enabled} />
                <Detail label="Origem da autorização" value={preferences?.whatsapp_opt_in_source} />
                <Detail label="Autorizado em" value={dateValue(preferences?.whatsapp_opt_in_at)} />
                <Detail label="Cancelado em" value={dateValue(preferences?.whatsapp_opt_out_at)} />
              </Section>

              <Section icon={Bell} title="Preferências de comunicação">
                <Detail label="E-mail habilitado" value={preferences?.email_enabled} />
                <Detail label="Push habilitado" value={preferences?.push_enabled} />
                <Detail label="Jornada habilitada" value={preferences?.lifecycle_enabled} />
                <Detail label="Conteúdo educativo" value={preferences?.product_education_enabled} />
                <Detail label="Conteúdo comercial" value={preferences?.commercial_enabled} />
                <Detail label="Preferências criadas em" value={dateValue(preferences?.created_at)} />
              </Section>

              <Section icon={Briefcase} title="Informações profissionais">
                <Detail label="Profissão / rótulo" value={p.professional_title} />
                <Detail label="Registro profissional" value={p.professional_register} />
                <Detail label="Contexto de atuação" value={p.work_context} />
                <Detail label="Logo personalizado" value={p.custom_logo_url} />
              </Section>

              <Section icon={CreditCard} title="Assinatura">
                <Detail label="Plano" value={getSubscriptionPlanLabel(p.subscription_plan)} />
                <Detail label="Status da assinatura" value={p.subscription_plan === 'courtesy' ? 'Regular / Ativo' : p.subscription_status} />
                <Detail label="Provedor de cobrança" value={p.billing_provider} />
                <Detail label="ID do cliente Stripe" value={p.stripe_customer_id} mono />
                <Detail label="Fim do período de teste" value={dateValue(p.trial_ends_at)} />
                <Detail label="Prazo para ativar o teste" value={dateValue(p.trial_activation_deadline_at)} />
                <Detail label="Teste ativado pela primeira evolução" value={dateValue(p.trial_activated_at)} />
                <Detail
                  label="Vencimento da assinatura"
                  value={p.subscription_plan === 'courtesy' || p.subscription_plan === 'none' ? 'Sem expiração' : dateValue(p.subscription_ends_at)}
                />
                <Detail label="Aviso de fim do teste enviado" value={dateValue(p.trial_expiration_email_sent_at)} />
              </Section>

              <Section icon={Database} title="Backup e integrações">
                <Detail label="Backup automático" value={p.auto_backup_enabled} />
                <Detail label="Frequência do backup" value={p.backup_frequency} />
                <Detail label="Último backup" value={dateValue(p.last_backup_at)} />
                <Detail label="Desconexão do Google forçada" value={p.force_google_disconnect} />
              </Section>

              <Section icon={Calendar} title="Datas da conta">
                <Detail label="Cadastro na plataforma" value={dateValue(p.created_at)} />
                <Detail label="Última atualização" value={dateValue(p.updated_at)} />
                <Detail label="Cadastro no Auth" value={dateValue(details.auth?.created_at)} />
                <Detail label="Último acesso" value={dateValue(details.auth?.last_sign_in_at)} />
                <Detail label="E-mail confirmado em" value={dateValue(details.auth?.email_confirmed_at)} />
                <Detail label="Consentimento atualizado em" value={dateValue(preferences?.updated_at)} />
              </Section>

              <Section icon={Globe} title="Origem no momento do cadastro">
                <Detail label="Canal de aquisição" value={getAcquisitionChannelLabel(signupAcquisition)} />
                <Detail label="Plataforma do cadastro" value={platformLabel(signupAcquisition)} />
                <Detail label="Distribuição" value={distributionLabel(signupAcquisition)} />
                <Detail label="UTM Source" value={marketingValue(signupAcquisition.utm_source)} />
                <Detail label="UTM Medium" value={marketingValue(signupAcquisition.utm_medium)} />
                <Detail label="UTM Campaign" value={signupAcquisition.utm_campaign} />
                <Detail label="Termo" value={signupAcquisition.utm_term} />
                <Detail label="Criativo" value={signupAcquisition.utm_content} />
                <Detail label="FBCLID" value={clickIdStatus(signupAcquisition.fbclid)} />
                <Detail label="GCLID" value={clickIdStatus(signupAcquisition.gclid)} />
                <Detail label="Página de entrada" value={signupAcquisition.landing_page} />
                <Detail
                  label="Método de atribuição"
                  value={signupAcquisition.attribution_method === 'google_play_install_referrer'
                    ? 'Google Play Install Referrer'
                    : signupAcquisition.attribution_method === 'url' ? 'Parâmetros da URL' : null}
                />
                <Detail label="Origem detectada em" value={dateValue(signupAcquisition.first_seen_at)} />
              </Section>

              <Section icon={Globe} title="Origem do primeiro acesso">
                <Detail label="Canal de aquisição" value={getAcquisitionChannelLabel(firstAcquisition)} />
                <Detail label="Plataforma do primeiro acesso" value={platformLabel(firstAcquisition)} />
                <Detail label="Distribuição" value={distributionLabel(firstAcquisition)} />
                <Detail label="UTM Source" value={marketingValue(firstAcquisition.utm_source)} />
                <Detail label="UTM Medium" value={marketingValue(firstAcquisition.utm_medium)} />
                <Detail label="UTM Campaign" value={firstAcquisition.utm_campaign} />
                <Detail label="Termo" value={firstAcquisition.utm_term} />
                <Detail label="Criativo" value={firstAcquisition.utm_content} />
                <Detail label="FBCLID" value={clickIdStatus(firstAcquisition.fbclid)} />
                <Detail label="GCLID" value={clickIdStatus(firstAcquisition.gclid)} />
                <Detail label="Página de entrada" value={firstAcquisition.landing_page} />
                <Detail label="Primeiro acesso detectado" value={dateValue(firstAcquisition.first_seen_at)} />
              </Section>

              <div className="rounded-2xl border border-brand-border/50 bg-brand-bg/30 p-4 text-xs text-brand-text-muted">
                <div className="flex items-center gap-2 font-semibold text-brand-text">
                  {preferences?.whatsapp_number ? <CheckCircle2 className="h-4 w-4 text-emerald-600" /> : <XCircle className="h-4 w-4 text-red-600" />}
                  {preferences?.whatsapp_number ? 'WhatsApp cadastrado' : 'WhatsApp ainda não cadastrado'}
                </div>
                <p className="mt-1">Os dados desta janela são carregados somente para administradores autenticados.</p>
              </div>
            </>
          ) : null}
        </div>

        <footer className="flex justify-end border-t border-brand-border/50 bg-brand-bg/30 px-5 py-4 sm:px-6">
          <button type="button" onClick={onClose} className="btn-primary px-5 py-2 text-xs font-semibold">Fechar</button>
        </footer>
      </div>
    </div>
  );
}

src/components/admin/ProfessionalFunnelK:
import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  CalendarDays,
  CheckCircle2,
  ChevronRight,
  Clock3,
  CreditCard,
  Filter,
  Globe2,
  LogIn,
  Loader2,
  Maximize2,
  Mail,
  MessageCircle,
  Minimize2,
  Monitor,
  RefreshCw,
  Search,
  Send,
  UserRound,
  Users,
  X,
} from 'lucide-react';
import { supabase } from '../../supabaseClient';
import {
  buildProfessionalFunnelMessage,
  buildProfessionalWhatsAppUrl,
  persistProfessionalWhatsAppTarget,
  readProfessionalWhatsAppTarget,
  type ProfessionalWhatsAppTarget,
} from '../../utils/professionalFunnelMessages';
import ProfessionalDetailsModal from './ProfessionalDetailsModal';

type StageKey = 'registered' | 'first_patient' | 'linked_record' | 'first_evolution' | 'returned' | 'paid';
type CommercialStatus = 'paid' | 'trial_active' | 'trial_expired' | 'no_plan';
type CommercialFilter = 'all' | CommercialStatus;
type OnboardingModeFilter = 'all' | 'guided' | 'explore' | 'unset';
type ContactFilter = 'all' | 'whatsapp_pending' | 'email_pending' | 'none';

type FunnelProfessional = {
  id: string;
  fullName: string;
  email: string;
  whatsappNumber: string | null;
  whatsappVerifiedAt: string | null;
  whatsappOptIn: boolean;
  whatsappSentAt: string | null;
  emailSentAt: string | null;
  accountStatus: string;
  createdAt: string;
  lastAccessAt: string | null;
  onboardingInitialMode: string | null;
  onboardingChoiceAt: string | null;
  subscriptionPlan: string | null;
  subscriptionStatus: string | null;
  subscriptionEndsAt: string | null;
  trialEndsAt: string | null;
  commercialStatus: CommercialStatus;
  stage: StageKey;
  stageReachedAt: string;
  metrics: {
    usageDaysCount: number;
    patientsCount: number;
    linkedRecordsCount: number;
    evolutionsCount: number;
  };
};

type FunnelBoard = {
  generatedAt: string;
  total: number;
  stageCounts: Record<StageKey, number>;
  commercialCounts: Record<CommercialStatus, number>;
  stages: Array<{ key: StageKey; label: string; description: string }>;
  professionals: FunnelProfessional[];
};

const FILTERS: Array<{ key: CommercialFilter; label: string }> = [
  { key: 'all', label: 'Todos' },
  { key: 'trial_active', label: 'Trial ativo' },
  { key: 'trial_expired', label: 'Trial esgotado' },
  { key: 'paid', label: 'Plano pago' },
  { key: 'no_plan', label: 'Sem plano' },
];

const ONBOARDING_MODE_FILTERS: Array<{ key: OnboardingModeFilter; label: string }> = [
  { key: 'all', label: 'Todos os caminhos' },
  { key: 'guided', label: 'Configurar com ajuda' },
  { key: 'explore', label: 'Conhecer primeiro' },
  { key: 'unset', label: 'Caminho não registrado' },
];

const CONTACT_FILTERS: Array<{ key: ContactFilter; label: string }> = [
  { key: 'all', label: 'Todos os contatos' },
  { key: 'whatsapp_pending', label: 'WhatsApp não enviado' },
  { key: 'email_pending', label: 'E-mail não enviado' },
  { key: 'none', label: 'Nenhum contato realizado' },
];

const STAGE_COLORS: Record<StageKey, { header: string; count: string; border: string }> = {
  registered: { header: 'bg-slate-100 text-slate-800', count: 'bg-slate-200 text-slate-800', border: 'border-slate-200' },
  first_patient: { header: 'bg-blue-50 text-blue-800', count: 'bg-blue-100 text-blue-800', border: 'border-blue-200' },
  linked_record: { header: 'bg-indigo-50 text-indigo-800', count: 'bg-indigo-100 text-indigo-800', border: 'border-indigo-200' },
  first_evolution: { header: 'bg-violet-50 text-violet-800', count: 'bg-violet-100 text-violet-800', border: 'border-violet-200' },
  returned: { header: 'bg-amber-50 text-amber-800', count: 'bg-amber-100 text-amber-800', border: 'border-amber-200' },
  paid: { header: 'bg-emerald-50 text-emerald-800', count: 'bg-emerald-100 text-emerald-800', border: 'border-emerald-200' },
};

const COMMERCIAL_PRESENTATION: Record<CommercialStatus, { label: string; className: string }> = {
  paid: { label: 'Plano pago', className: 'border-emerald-200 bg-emerald-50 text-emerald-700' },
  trial_active: { label: 'Trial ativo', className: 'border-sky-200 bg-sky-50 text-sky-700' },
  trial_expired: { label: 'Trial esgotado', className: 'border-red-200 bg-red-50 text-red-700' },
  no_plan: { label: 'Sem plano', className: 'border-slate-200 bg-slate-50 text-slate-600' },
};

const NEXT_ACTION: Record<StageKey, string> = {
  registered: 'Próximo: verificar WhatsApp',
  first_patient: 'Próximo: vincular prontuário',
  linked_record: 'Próximo: concluir evolução',
  first_evolution: 'Próximo: retornar ao app',
  returned: 'Próximo: assinar um plano',
  paid: 'Fluxo principal concluído',
};

const formatDate = (value?: string | null) => {
  if (!value) return 'Não informado';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return 'Não informado';
  return parsed.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' });
};

const formatDateTime = (value?: string | null) => {
  if (!value) return 'Não informado';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return 'Não informado';
  return parsed.toLocaleString('pt-BR');
};

const initialModeLabel = (mode: string | null) => {
  if (mode === 'guided') return 'Configurar com ajuda';
  if (mode === 'explore') return 'Conhecer o app primeiro';
  return 'Caminho não registrado';
};

const daysUntil = (value?: string | null) => {
  if (!value) return null;
  const timestamp = new Date(value).getTime();
  if (!Number.isFinite(timestamp)) return null;
  return Math.ceil((timestamp - Date.now()) / (24 * 60 * 60 * 1000));
};

function ProfessionalCard({
  professional,
  onOpen,
  onOpenEmail,
  onToggleContact,
  contactUpdatingKey,
  whatsappTarget,
}: {
  professional: FunnelProfessional;
  onOpen: () => void;
  onOpenEmail: () => void;
  onToggleContact: (channel: 'whatsapp' | 'email') => void;
  contactUpdatingKey: string;
  whatsappTarget: ProfessionalWhatsAppTarget;
}) {
  const commercial = COMMERCIAL_PRESENTATION[professional.commercialStatus];
  const trialDays = daysUntil(professional.trialEndsAt);
  const message = buildProfessionalFunnelMessage({
    fullName: professional.fullName,
    stage: professional.stage,
    commercialStatus: professional.commercialStatus,
    whatsappVerified: Boolean(professional.whatsappVerifiedAt),
  });
  const whatsappUrl = professional.whatsappNumber
    ? buildProfessionalWhatsAppUrl(professional.whatsappNumber, message.whatsappText, whatsappTarget)
    : null;
  const hasEmail = professional.email.includes('@');
  const whatsappUpdating = contactUpdatingKey === `${professional.id}:whatsapp`;
  const emailUpdating = contactUpdatingKey === `${professional.id}:email`;
  const nextAction = professional.stage === 'registered' && professional.whatsappVerifiedAt
    ? 'Próximo: continuar configuração'
    : NEXT_ACTION[professional.stage];
  const initials = professional.fullName
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('') || 'PR';

  return (
    <article className="overflow-hidden rounded-2xl border border-brand-border/70 bg-white shadow-sm transition hover:-translate-y-0.5 hover:border-brand-primary/35 hover:shadow-md">
      <button
        type="button"
        onClick={onOpen}
        className="group w-full p-4 text-left focus:outline-none focus:ring-2 focus:ring-inset focus:ring-brand-primary/30"
        aria-label={`Abrir detalhes de ${professional.fullName}`}
      >
        <div className="flex items-start gap-3">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-brand-primary/10 text-xs font-bold text-brand-primary">
            {initials}
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <p className="truncate text-sm font-bold text-brand-text" title={professional.fullName}>{professional.fullName}</p>
                <p className="truncate text-[11px] text-brand-text-muted" title={professional.email}>{professional.email}</p>
              </div>
              <ChevronRight className="mt-1 shrink-0 text-brand-text-muted transition group-hover:translate-x-0.5 group-hover:text-brand-primary" size={16} />
            </div>
          </div>
        </div>

        <div className="mt-3 flex flex-wrap gap-1.5">
          <span className={`rounded-full border px-2 py-0.5 text-[10px] font-bold ${commercial.className}`}>{commercial.label}</span>
          <span className="rounded-full border border-brand-border bg-brand-bg/60 px-2 py-0.5 text-[10px] font-semibold text-brand-text-muted">
            {initialModeLabel(professional.onboardingInitialMode)}
          </span>
          <span className={`rounded-full border px-2 py-0.5 text-[10px] font-semibold ${professional.whatsappVerifiedAt
            ? 'border-emerald-200 bg-emerald-50 text-emerald-700'
            : 'border-amber-200 bg-amber-50 text-amber-700'}`}>
            {professional.whatsappVerifiedAt ? 'WhatsApp confirmado' : 'WhatsApp pendente'}
          </span>
          {professional.accountStatus !== 'active' && (
            <span className="rounded-full border border-amber-200 bg-amber-50 px-2 py-0.5 text-[10px] font-bold text-amber-700">
              Conta {professional.accountStatus === 'pending' ? 'pendente' : 'inativa'}
            </span>
          )}
        </div>

        <div className="mt-3 grid grid-cols-3 gap-1.5 text-center">
          <div className="rounded-lg bg-brand-bg/60 px-1 py-2" title="Pacientes cadastrados">
            <p className="text-sm font-bold text-brand-text">{professional.metrics.patientsCount}</p>
            <p className="text-[9px] uppercase text-brand-text-muted">Pacientes</p>
          </div>
          <div className="rounded-lg bg-brand-bg/60 px-1 py-2" title="Evoluções concluídas ou registradas">
            <p className="text-sm font-bold text-brand-text">{professional.metrics.evolutionsCount}</p>
            <p className="text-[9px] uppercase text-brand-text-muted">Evoluções</p>
          </div>
          <div className="rounded-lg bg-brand-bg/60 px-1 py-2" title="Dias com uso real da plataforma">
            <p className="text-sm font-bold text-brand-text">{professional.metrics.usageDaysCount}</p>
            <p className="text-[9px] uppercase text-brand-text-muted">Dias de uso</p>
          </div>
        </div>

        <div className="mt-3 space-y-1.5 border-t border-brand-border/50 pt-3 text-[10px] text-brand-text-muted">
          <p className="flex items-center gap-1.5"><CalendarDays size={12} />Cadastro: {formatDate(professional.createdAt)}</p>
          <p className="flex items-center gap-1.5"><LogIn size={12} />Último acesso: {formatDateTime(professional.lastAccessAt)}</p>
          {professional.commercialStatus === 'trial_active' && trialDays !== null && (
            <p className="flex items-center gap-1.5 text-sky-700"><Clock3 size={12} />Trial termina {trialDays <= 0 ? 'hoje' : `em ${trialDays} dia${trialDays === 1 ? '' : 's'}`}</p>
          )}
          <p className={`flex items-center gap-1.5 font-semibold ${professional.stage === 'paid' ? 'text-emerald-700' : 'text-brand-primary'}`}>
            {professional.stage === 'paid' ? <CheckCircle2 size={12} /> : <ChevronRight size={12} />}{nextAction}
          </p>
        </div>
      </button>

      {(whatsappUrl || hasEmail) && <div className="border-t border-brand-border/60 bg-brand-bg/20 p-2.5">
        <div className={`grid gap-2 ${whatsappUrl && hasEmail ? 'grid-cols-2' : 'grid-cols-1'}`}>
        {whatsappUrl && (
          <a
            href={whatsappUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center justify-center gap-1.5 rounded-lg border border-emerald-200 bg-emerald-50 px-2 py-2 text-[11px] font-bold text-emerald-700 transition hover:bg-emerald-100"
            aria-label={`Preparar WhatsApp para ${professional.fullName}`}
            title={`${whatsappTarget === 'desktop' ? 'Abrir no WhatsApp Desktop' : 'Abrir no WhatsApp Web'}${professional.whatsappOptIn ? '' : '; não há opt-in registrado na plataforma'}`}
          >
            <MessageCircle size={14} />WhatsApp
          </a>
        )}
        {hasEmail && (
          <button
            type="button"
            onClick={onOpenEmail}
            className="inline-flex items-center justify-center gap-1.5 rounded-lg border border-sky-200 bg-sky-50 px-2 py-2 text-[11px] font-bold text-sky-700 transition hover:bg-sky-100"
            aria-label={`Preparar e-mail para ${professional.fullName}`}
          >
            <Mail size={14} />E-mail
          </button>
        )}
        </div>
        <div className={`mt-2 grid gap-2 ${whatsappUrl && hasEmail ? 'grid-cols-2' : 'grid-cols-1'}`}>
          {whatsappUrl && (
            <button
              type="button"
              onClick={() => onToggleContact('whatsapp')}
              disabled={whatsappUpdating}
              aria-pressed={Boolean(professional.whatsappSentAt)}
              className={`inline-flex items-center justify-center gap-1 rounded-lg border px-2 py-1.5 text-[10px] font-semibold transition ${professional.whatsappSentAt
                ? 'border-emerald-300 bg-emerald-100 text-emerald-800 hover:bg-emerald-200'
                : 'border-brand-border bg-white text-brand-text-muted hover:border-emerald-300 hover:text-emerald-700'}`}
            >
              {whatsappUpdating ? <Loader2 className="animate-spin" size={12} /> : <CheckCircle2 size={12} />}{professional.whatsappSentAt ? 'WhatsApp enviado' : 'Marcar WhatsApp enviado'}
            </button>
          )}
          {hasEmail && (
            <button
              type="button"
              onClick={() => onToggleContact('email')}
              disabled={emailUpdating}
              aria-pressed={Boolean(professional.emailSentAt)}
              className={`inline-flex items-center justify-center gap-1 rounded-lg border px-2 py-1.5 text-[10px] font-semibold transition ${professional.emailSentAt
                ? 'border-sky-300 bg-sky-100 text-sky-800 hover:bg-sky-200'
                : 'border-brand-border bg-white text-brand-text-muted hover:border-sky-300 hover:text-sky-700'}`}
            >
              {emailUpdating ? <Loader2 className="animate-spin" size={12} /> : <CheckCircle2 size={12} />}{professional.emailSentAt ? 'E-mail enviado' : 'Marcar e-mail enviado'}
            </button>
          )}
        </div>
      </div>}
    </article>
  );
}

function FunnelEmailModal({ professional, onClose, onEmailSent }: {
  professional: FunnelProfessional | null;
  onClose: () => void;
  onEmailSent: (professionalId: string, sentAt: string | null) => void;
}) {
  const [sending, setSending] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    setSending(false);
    setError('');
    setSuccess('');
  }, [professional?.id]);

  useEffect(() => {
    if (!professional) return;
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !sending) onClose();
    };
    window.addEventListener('keydown', handleEscape);
    return () => window.removeEventListener('keydown', handleEscape);
  }, [onClose, professional, sending]);

  if (!professional) return null;

  const content = buildProfessionalFunnelMessage({
    fullName: professional.fullName,
    stage: professional.stage,
    commercialStatus: professional.commercialStatus,
    whatsappVerified: Boolean(professional.whatsappVerifiedAt),
  });
  const firstName = professional.fullName.trim().split(/\s+/)[0] || 'profissional';

  const sendEmail = async () => {
    setSending(true);
    setError('');
    setSuccess('');
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData.session?.access_token;
      if (!token) throw new Error('Sessão administrativa não encontrada.');
      const response = await fetch('/api/admin/professional-funnel/email', {
        method: 'POST',
        cache: 'no-store',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ professionalId: professional.id, stage: professional.stage }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error || 'Não foi possível enviar o e-mail.');
      onEmailSent(professional.id, payload.emailSentAt || new Date().toISOString());
      setSuccess(`E-mail enviado com sucesso via ${payload.provider === 'brevo' ? 'Brevo' : 'SMTP'}.`);
    } catch (sendError) {
      setError(sendError instanceof Error ? sendError.message : 'Não foi possível enviar o e-mail.');
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/55 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label="Preparar e-mail do funil">
      <div className="flex max-h-[92vh] w-full max-w-3xl flex-col overflow-hidden rounded-3xl border border-brand-border bg-white shadow-2xl">
        <header className="flex items-start justify-between gap-4 border-b border-brand-border px-5 py-4 sm:px-6">
          <div>
            <p className="text-[10px] font-bold uppercase tracking-wider text-brand-primary">E-mail conforme a etapa atual</p>
            <h2 className="mt-1 font-display text-xl font-bold text-brand-text">Revisar e enviar</h2>
            <p className="mt-1 text-xs text-brand-text-muted">O conteúdo está pronto e não precisa ser editado.</p>
          </div>
          <button type="button" onClick={onClose} disabled={sending} className="rounded-full p-2 text-brand-text-muted transition hover:bg-brand-bg hover:text-brand-text disabled:opacity-50" aria-label="Fechar e-mail">
            <X size={20} />
          </button>
        </header>

        <div className="overflow-y-auto p-5 sm:p-6">
          <div className="mb-4 grid gap-3 rounded-2xl border border-brand-border bg-brand-bg/30 p-4 text-xs sm:grid-cols-2">
            <div><span className="block font-bold uppercase tracking-wide text-brand-text-muted">Para</span><span className="mt-1 block break-all font-semibold text-brand-text">{professional.fullName} · {professional.email}</span></div>
            <div><span className="block font-bold uppercase tracking-wide text-brand-text-muted">Assunto</span><span className="mt-1 block font-semibold text-brand-text">{content.subject}</span></div>
          </div>

          <div className="mx-auto max-w-2xl overflow-hidden rounded-2xl border border-brand-border bg-white shadow-sm">
            <div className="flex items-center justify-between border-b border-brand-border px-6 py-4">
              <span className="font-display text-base font-extrabold text-brand-primary">Evolução Clínica</span>
              <span className="text-[10px] font-bold uppercase tracking-wider text-brand-text-muted">Seu próximo passo</span>
            </div>
            <div className="bg-gradient-to-br from-brand-primary to-brand-secondary px-6 py-7 text-white">
              <h3 className="text-xl font-bold">{content.subject}</h3>
              <p className="mt-2 text-sm text-white/85">{content.preheader}</p>
            </div>
            <div className="space-y-4 px-6 py-7 text-sm leading-relaxed text-brand-text">
              <p>Olá, <strong>{firstName}</strong>!</p>
              {content.paragraphs.map((paragraph) => <p key={paragraph}>{paragraph}</p>)}
              <div className="pt-2 text-center">
                <span className="inline-flex rounded-xl bg-brand-primary px-5 py-3 font-bold text-white">{content.actionLabel}</span>
              </div>
            </div>
            <div className="border-t border-brand-border bg-brand-bg/40 px-6 py-4 text-center text-[10px] text-brand-text-muted">
              Mensagem enviada pela equipe da Evolução Clínica · Preferências de comunicação · Descadastro · Suporte
            </div>
          </div>

          {error && <div className="mt-4 rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</div>}
          {success && <div className="mt-4 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm font-semibold text-emerald-700">{success}</div>}
        </div>

        <footer className="border-t border-brand-border bg-white p-4 sm:px-6">
          <button
            type="button"
            onClick={() => void sendEmail()}
            disabled={sending || Boolean(success)}
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-brand-primary px-5 py-3 text-sm font-bold text-white transition hover:bg-brand-primary-hover disabled:cursor-not-allowed disabled:opacity-60"
          >
            {sending ? <Loader2 className="animate-spin" size={18} /> : success ? <CheckCircle2 size={18} /> : <Send size={18} />}
            {sending ? 'Enviando...' : success ? 'E-mail enviado' : 'Enviar e-mail'}
          </button>
        </footer>
      </div>
    </div>
  );
}

export default function ProfessionalFunnelKanban() {
  const [board, setBoard] = useState<FunnelBoard | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [commercialFilter, setCommercialFilter] = useState<CommercialFilter>('all');
  const [onboardingModeFilter, setOnboardingModeFilter] = useState<OnboardingModeFilter>('all');
  const [contactFilter, setContactFilter] = useState<ContactFilter>('all');
  const [selectedProfessional, setSelectedProfessional] = useState<FunnelProfessional | null>(null);
  const [emailProfessional, setEmailProfessional] = useState<FunnelProfessional | null>(null);
  const [whatsappTarget, setWhatsappTarget] = useState<ProfessionalWhatsAppTarget>(() => readProfessionalWhatsAppTarget());
  const [contactUpdatingKey, setContactUpdatingKey] = useState('');
  const [isFullscreen, setIsFullscreen] = useState(false);

  useEffect(() => {
    if (!isFullscreen) return;

    const previousBodyOverflow = document.body.style.overflow;
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setIsFullscreen(false);
    };

    document.body.style.overflow = 'hidden';
    window.addEventListener('keydown', handleEscape);
    return () => {
      document.body.style.overflow = previousBodyOverflow;
      window.removeEventListener('keydown', handleEscape);
    };
  }, [isFullscreen]);

  const loadBoard = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData.session?.access_token;
      if (!token) throw new Error('Sessão administrativa não encontrada.');
      const response = await fetch('/api/admin/professional-funnel', {
        cache: 'no-store',
        headers: { Authorization: `Bearer ${token}` },
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error || 'Não foi possível carregar o funil dos profissionais.');
      setBoard(payload);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : 'Não foi possível carregar o funil dos profissionais.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void loadBoard(); }, [loadBoard]);

  const handleWhatsAppTargetChange = () => {
    const nextTarget: ProfessionalWhatsAppTarget = whatsappTarget === 'web' ? 'desktop' : 'web';
    setWhatsappTarget(nextTarget);
    persistProfessionalWhatsAppTarget(nextTarget);
  };

  const handleContactStatus = async (professionalId: string, channel: 'whatsapp' | 'email') => {
    if (!board) return;
    const professional = board.professionals.find((item) => item.id === professionalId);
    if (!professional) return;
    const key = `${professionalId}:${channel}`;
    const sent = channel === 'whatsapp' ? !professional.whatsappSentAt : !professional.emailSentAt;
    setContactUpdatingKey(key);
    setError('');
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData.session?.access_token;
      if (!token) throw new Error('Sessão administrativa não encontrada.');
      const response = await fetch('/api/admin/professional-funnel/contact-status', {
        method: 'POST',
        cache: 'no-store',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ professionalId, channel, sent }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error || 'Não foi possível atualizar a marcação de contato.');
      setBoard((current) => current ? {
        ...current,
        professionals: current.professionals.map((item) => item.id === professionalId
          ? {
            ...item,
            whatsappSentAt: channel === 'whatsapp' ? payload.markedAt : item.whatsappSentAt,
            emailSentAt: channel === 'email' ? payload.markedAt : item.emailSentAt,
          }
          : item),
      } : current);
    } catch (contactError) {
      setError(contactError instanceof Error ? contactError.message : 'Não foi possível atualizar a marcação de contato.');
    } finally {
      setContactUpdatingKey('');
    }
  };

  const markEmailSentAfterDelivery = (professionalId: string, sentAt: string | null) => {
    setBoard((current) => current ? {
      ...current,
      professionals: current.professionals.map((item) => item.id === professionalId ? { ...item, emailSentAt: sentAt } : item),
    } : current);
  };

  const filteredProfessionals = useMemo(() => {
    if (!board) return [];
    const normalizedSearch = search.trim().toLocaleLowerCase('pt-BR');
    return board.professionals.filter((professional) => {
      const matchesFilter = commercialFilter === 'all' || professional.commercialStatus === commercialFilter;
      const matchesMode = onboardingModeFilter === 'all'
        || (onboardingModeFilter === 'unset' ? !professional.onboardingInitialMode : professional.onboardingInitialMode === onboardingModeFilter);
      const matchesContact = contactFilter === 'all'
        || (contactFilter === 'whatsapp_pending' && !professional.whatsappSentAt)
        || (contactFilter === 'email_pending' && !professional.emailSentAt)
        || (contactFilter === 'none' && !professional.whatsappSentAt && !professional.emailSentAt);
      const matchesSearch = !normalizedSearch
        || professional.fullName.toLocaleLowerCase('pt-BR').includes(normalizedSearch)
        || professional.email.toLocaleLowerCase('pt-BR').includes(normalizedSearch);
      return matchesFilter && matchesMode && matchesContact && matchesSearch;
    });
  }, [board, commercialFilter, onboardingModeFilter, contactFilter, search]);

  const filteredCounts = useMemo(() => filteredProfessionals.reduce<Partial<Record<StageKey, number>>>((counts, professional) => {
    counts[professional.stage] = (counts[professional.stage] || 0) + 1;
    return counts;
  }, {}), [filteredProfessionals]);

  return (
    <div
      className={isFullscreen ? 'fixed inset-0 z-[80] min-h-full overflow-y-auto bg-brand-bg p-3 sm:p-6' : 'space-y-5 animate-fadeIn'}
      data-testid="professional-funnel-kanban"
      data-fullscreen={isFullscreen ? 'true' : 'false'}
    >
      <section className="rounded-3xl border border-brand-primary/15 bg-white p-5 shadow-sm sm:p-6">
        <div className="flex flex-col gap-4 xl:flex-row xl:items-start xl:justify-between">
          <div>
            <div className="flex items-center gap-2 text-brand-primary">
              <Users size={22} />
              <h1 className="font-display text-2xl font-bold">Funil dos profissionais</h1>
            </div>
            <p className="mt-1 max-w-3xl text-sm text-brand-text-muted">
              Cada profissional aparece somente na etapa mais avançada que alcançou. O caminho inicial fica como etiqueta e filtro de análise.
            </p>
          </div>
          <div className="flex flex-col items-stretch gap-2 sm:flex-row sm:items-center">
            <button
              type="button"
              onClick={() => setIsFullscreen((current) => !current)}
              aria-pressed={isFullscreen}
              data-testid="professional-funnel-fullscreen-toggle"
              title={isFullscreen ? 'Voltar à exibição normal' : 'Abrir funil em tela cheia'}
              className="btn-outline inline-flex items-center justify-center gap-2 px-4 py-2 text-xs"
            >
              {isFullscreen ? <Minimize2 size={14} /> : <Maximize2 size={14} />}
              {isFullscreen ? 'Voltar à exibição normal' : 'Tela cheia'}
            </button>
            <div className="flex items-center justify-between gap-3 rounded-xl border border-brand-border bg-brand-bg/30 px-3 py-2" title="A preferência fica salva neste navegador administrativo.">
              <div className="flex items-center gap-2">
                {whatsappTarget === 'desktop' ? <Monitor size={15} className="text-emerald-700" /> : <Globe2 size={15} className="text-emerald-700" />}
                <div>
                  <span className="block text-[10px] font-bold uppercase tracking-wide text-brand-text-muted">Destino do WhatsApp</span>
                  <span className="block text-xs font-semibold text-brand-text">{whatsappTarget === 'desktop' ? 'WhatsApp Desktop' : 'WhatsApp Web'}</span>
                </div>
              </div>
              <button
                type="button"
                role="switch"
                aria-checked={whatsappTarget === 'desktop'}
                aria-label="Alternar destino do WhatsApp entre Web e Desktop"
                onClick={handleWhatsAppTargetChange}
                className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition ${whatsappTarget === 'desktop' ? 'bg-emerald-600' : 'bg-slate-300'}`}
              >
                <span className={`inline-block h-5 w-5 rounded-full bg-white shadow-sm transition-transform ${whatsappTarget === 'desktop' ? 'translate-x-5' : 'translate-x-0.5'}`} />
              </button>
            </div>
            <button type="button" onClick={() => void loadBoard()} disabled={loading} className="btn-outline inline-flex items-center justify-center gap-2 px-4 py-2 text-xs">
              <RefreshCw size={14} className={loading ? 'animate-spin' : ''} /> Atualizar dados
            </button>
          </div>
        </div>

        {board && (
          <div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
            <div className="rounded-2xl border border-brand-border bg-brand-bg/30 p-4">
              <p className="flex items-center gap-2 text-xs font-semibold text-brand-text-muted"><UserRound size={14} />Profissionais</p>
              <p className="mt-1 text-2xl font-bold text-brand-primary">{board.total}</p>
            </div>
            <div className="rounded-2xl border border-sky-200 bg-sky-50 p-4">
              <p className="flex items-center gap-2 text-xs font-semibold text-sky-700"><Clock3 size={14} />Trials ativos</p>
              <p className="mt-1 text-2xl font-bold text-sky-800">{board.commercialCounts.trial_active}</p>
            </div>
            <div className="rounded-2xl border border-red-200 bg-red-50 p-4">
              <p className="flex items-center gap-2 text-xs font-semibold text-red-700"><Clock3 size={14} />Trials esgotados</p>
              <p className="mt-1 text-2xl font-bold text-red-800">{board.commercialCounts.trial_expired}</p>
            </div>
            <div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4">
              <p className="flex items-center gap-2 text-xs font-semibold text-emerald-700"><CreditCard size={14} />Planos pagos</p>
              <p className="mt-1 text-2xl font-bold text-emerald-800">{board.commercialCounts.paid}</p>
            </div>
          </div>
        )}

        <div className="mt-5 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <label className="relative block w-full lg:max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-brand-text-muted" size={16} />
            <span className="sr-only">Buscar profissional</span>
            <input
              type="search"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Buscar por nome ou e-mail"
              className="w-full rounded-xl border border-brand-border bg-white py-2.5 pl-10 pr-3 text-sm outline-none transition focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/10"
            />
          </label>
          <div className="flex flex-col gap-2 lg:items-end">
            <div className="flex items-center gap-2 overflow-x-auto pb-1" aria-label="Filtrar por situação comercial">
              <Filter className="shrink-0 text-brand-text-muted" size={15} />
              {FILTERS.map((filter) => (
                <button
                  key={filter.key}
                  type="button"
                  onClick={() => setCommercialFilter(filter.key)}
                  aria-pressed={commercialFilter === filter.key}
                  className={`shrink-0 rounded-full border px-3 py-1.5 text-[11px] font-semibold transition ${commercialFilter === filter.key
                    ? 'border-brand-primary bg-brand-primary text-white'
                    : 'border-brand-border bg-white text-brand-text-muted hover:border-brand-primary/40 hover:text-brand-primary'}`}
                >
                  {filter.label}
                </button>
              ))}
            </div>
            <div className="flex items-center gap-2 overflow-x-auto pb-1" aria-label="Filtrar por caminho inicial">
              <span className="shrink-0 text-[10px] font-bold uppercase tracking-wide text-brand-text-muted">Caminho:</span>
              {ONBOARDING_MODE_FILTERS.map((filter) => (
                <button
                  key={filter.key}
                  type="button"
                  onClick={() => setOnboardingModeFilter(filter.key)}
                  aria-pressed={onboardingModeFilter === filter.key}
                  className={`shrink-0 rounded-full border px-3 py-1.5 text-[11px] font-semibold transition ${onboardingModeFilter === filter.key
                    ? 'border-brand-primary bg-brand-primary text-white'
                    : 'border-brand-border bg-white text-brand-text-muted hover:border-brand-primary/40 hover:text-brand-primary'}`}
                >
                  {filter.label}
                </button>
              ))}
            </div>
            <div className="flex items-center gap-2 overflow-x-auto pb-1" aria-label="Filtrar por contato">
              <span className="shrink-0 text-[10px] font-bold uppercase tracking-wide text-brand-text-muted">Contato:</span>
              {CONTACT_FILTERS.map((filter) => (
                <button
                  key={filter.key}
                  type="button"
                  onClick={() => setContactFilter(filter.key)}
                  aria-pressed={contactFilter === filter.key}
                  className={`shrink-0 rounded-full border px-3 py-1.5 text-[11px] font-semibold transition ${contactFilter === filter.key
                    ? 'border-brand-primary bg-brand-primary text-white'
                    : 'border-brand-border bg-white text-brand-text-muted hover:border-brand-primary/40 hover:text-brand-primary'}`}
                >
                  {filter.label}
                </button>
              ))}
            </div>
          </div>
        </div>
      </section>

      {loading && !board ? (
        <div className="flex min-h-64 items-center justify-center gap-2 rounded-3xl border border-brand-border bg-white text-sm text-brand-text-muted">
          <Loader2 className="animate-spin" size={22} />Carregando todos os profissionais...
        </div>
      ) : error ? (
        <div className="rounded-2xl border border-red-200 bg-red-50 p-5 text-sm text-red-700">{error}</div>
      ) : board ? (
        <>
          <div className="flex items-center justify-between px-1 text-xs text-brand-text-muted">
            <span>{filteredProfessionals.length} de {board.total} profissionais exibidos</span>
            <span>Atualizado em {formatDateTime(board.generatedAt)}</span>
          </div>
          <div className="overflow-x-auto pb-4" aria-label="Funil kanban dos profissionais">
            <div className="flex min-w-max items-start gap-4">
              {board.stages.map((stage) => {
                const colors = STAGE_COLORS[stage.key];
                const professionals = filteredProfessionals.filter((professional) => professional.stage === stage.key);
                return (
                  <section key={stage.key} className={`w-[300px] shrink-0 overflow-hidden rounded-2xl border bg-brand-bg/20 ${colors.border}`} data-stage={stage.key}>
                    <header className={`min-h-[106px] border-b p-4 ${colors.header} ${colors.border}`}>
                      <div className="flex items-center justify-between gap-3">
                        <h2 className="text-sm font-bold">{stage.label}</h2>
                        <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${colors.count}`}>{filteredCounts[stage.key] || 0}</span>
                      </div>
                      <p className="mt-2 text-[11px] leading-relaxed opacity-80">{stage.description}</p>
                    </header>
                    <div className="max-h-[62vh] space-y-3 overflow-y-auto p-3">
                      {professionals.length > 0 ? professionals.map((professional) => (
                        <ProfessionalCard
                          key={professional.id}
                          professional={professional}
                          onOpen={() => setSelectedProfessional(professional)}
                          onOpenEmail={() => setEmailProfessional(professional)}
                          onToggleContact={(channel) => void handleContactStatus(professional.id, channel)}
                          contactUpdatingKey={contactUpdatingKey}
                          whatsappTarget={whatsappTarget}
                        />
                      )) : (
                        <div className="rounded-xl border border-dashed border-brand-border bg-white/60 px-3 py-8 text-center text-xs text-brand-text-muted">
                          Nenhum profissional nesta etapa com os filtros atuais.
                        </div>
                      )}
                    </div>
                  </section>
                );
              })}
            </div>
          </div>
        </>
      ) : null}

      <ProfessionalDetailsModal
        professional={selectedProfessional ? {
          id: selectedProfessional.id,
          full_name: selectedProfessional.fullName,
          google_email: selectedProfessional.email,
        } : null}
        onClose={() => setSelectedProfessional(null)}
      />
      <FunnelEmailModal professional={emailProfessional} onClose={() => setEmailProfessional(null)} onEmailSent={markEmailSentAfterDelivery} />
    </div>
  );
}

